-- Figures live in public/q/oct25/. Ids are fixed, so running this file again updates the test instead of copying it.

-- PeaklyTest Oct 2025 · Reading & Writing · Module 1
insert into public.tests (id, title, section, description, duration_min, position, published, form_title, module_no)
values ('4335dcd1-5558-5119-8672-476dd0c9f5a5', 'PeaklyTest Oct 2025 · Reading & Writing · Module 1', 'Reading & Writing', 'Reading & Writing, Module 1 of the Oct 2025 PeaklyTest · 27 questions · 32 minutes', 32, 180, true, 'PeaklyTest Oct 2025 · Reading & Writing', 1)
on conflict (id) do update set title = excluded.title, section = excluded.section, description = excluded.description,
  duration_min = excluded.duration_min, position = excluded.position, form_title = excluded.form_title, module_no = excluded.module_no;
insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('6705f07e-9910-5c71-bded-50d1b7af0faf', '4335dcd1-5558-5119-8672-476dd0c9f5a5', 'Which choice completes the text with the most logical and precise word or phrase?', '["a division", "a convergence", "an expiration", "a succession"]'::jsonb, 1, 'Broods of periodical cicadas (inch-long winged insects) emerge for six weeks in late spring on a cycle of either 13 or 17 years. In 2024, the emergencies of the Great Southern Brood (on a 13-year cycle) and the Northern Illinois Brood (on a 17-year cycle) coincided in the Midwest and Southeast United States, _______ that happens only once every 221 years. Sixteen states were covered with a trillion cicadas.'),
  ('7412a677-25db-5e19-a8ee-bbe96ec7ca04', '4335dcd1-5558-5119-8672-476dd0c9f5a5', 'Which choice completes the text with the most logical and precise word or phrase?', '["overshadow", "begin", "distract", "honor"]'::jsonb, 2, 'The National Heritage Fellowship was created to _____ exceptional folk and traditional artists in the United States. One artist who received the fellowship, the taiko drummer Seiichi Tanaka, was chosen for his lifetime contributions to the arts.'),
  ('2deb09db-3e0b-57b6-8fa1-1791c651f144', '4335dcd1-5558-5119-8672-476dd0c9f5a5', 'Which choice completes the text with the most logical and precise word or phrase?', '["invent", "combine", "celebrate", "withhold"]'::jsonb, 3, 'Japanese animator and director Hayao Miyazaki often includes fantasy elements in otherwise realistic settings in his movies, but he tends to ________ details and exposition about those elements. Miyazaki simply presents fantastical characters and actions with little backstory or explanation, encouraging viewers to embrace the presence of the extraordinary in everyday life.'),
  ('470c4add-07ac-5c59-9a2a-1cb07278ef0d', '4335dcd1-5558-5119-8672-476dd0c9f5a5', 'As used in the text, what does the word “good” most nearly mean?', '["Reliable", "Courteous", "Considerable", "Capable"]'::jsonb, 4, 'The following text is from Charles Chesnutt’s 1905 novel The Colonel’s Dream.

Mr. French, the senior partner, who sat opposite Kirby, was an older man—a safe guess would have placed him somewhere in the debatable ground between forty and fifty; of a <u>good</u> height, as could be seen even from the seated figure, the upper part of which was held erect with the unconscious ease which one associates with military training.'),
  ('dedc4bfd-4c52-5e32-818a-06d457d39fb3', '4335dcd1-5558-5119-8672-476dd0c9f5a5', 'Which choice completes the text with the most logical and precise word or phrase?', '["discovers", "renounces", "complains", "denotes"]'::jsonb, 5, 'Portoviejo, Ecuador, was named a City of Gastronomy by UNESCO in 2019, a title that ______ that Portoviejo has a unique and vibrant food culture worthy of celebration.'),
  ('e2ef309f-12f6-5dc9-9b83-5563a2e58ebe', '4335dcd1-5558-5119-8672-476dd0c9f5a5', 'Which choice best describes the function of underlined sentence in the text as a whole?', '["It specifies potential applications of the approach that Heberling and Burke used in their study.", "It explains why the research methodology selected by Heberling and Burke is not widely used.", "It emphasizes the importance of Heberling and Burke’s findings about the DNA of fungi.", "It offers commentary on the significance of the approach that Heberling and Burke used for their study."]'::jsonb, 6, 'Svante Pääbo and other researchers studying the history of organisms have long utilized ancient DNA—DNA recovered from ancient organic material that has been preserved under natural conditions. However, J. Mason Heberling and David J. Burke’s 2019 study of the evolutionary trajectory of arbuscular mycorrhizal fungi instead relied on historical DNA—genomic data incidentally preserved in specimens that are housed in natural history collections—<u>thus capitalizing on the</u> <u>research potential offered by a vast but hitherto relatively underutilized source of insight into the</u> <u>biological past.</u>'),
  ('c92e32b3-3794-5fcc-af90-ffdb1bdaffbb', '4335dcd1-5558-5119-8672-476dd0c9f5a5', 'Which choice best describes the function of underlined sentence in the text as a whole?', '["To illustrate an important real-world implication of LaBerge and team’s main finding.", "To offer key evidence that undermines LaBerge and team’s initial hypothesis.", "To show the unexpected result that led LaBerge and team to change the focus of their study.", "To identify a comparable circumstance that helps justify LaBerge and team’s conclusion."]'::jsonb, 7, 'Curious about how people visually perceive objects in their dreams, Stephen LaBerge and team recruited lucid dreamers—people aware that they’re dreaming as it’s happening—for a research study. These participants were reliably able to signal when they had entered a dream state; the team then observed participants’ eye movements as they slept. <u>The smoothness with which participants’ eyes</u> <u>tracked objects in their dreams closely matched how sighted people who are awake visually track</u> <u>objects around them</u> , suggesting to the team that the brain perceives dream objects as the product of something other than pure imagination.'),
  ('22442910-c3c1-5714-b1b1-7862c92893f6', '4335dcd1-5558-5119-8672-476dd0c9f5a5', 'Which choice best states the main idea of the text?', '["Yung has experienced significant personal growth in the time since his arrival to New York City in 1847.", "The journey to New York City was extremely tiring for Yung.", "The architecture in New York City is more beautiful than that in London.", "New York City has become more developed and populated since Yung’s arrival in 1847."]'::jsonb, 8, 'The following text is from Yung Wing’s 1909 memoir My Life in China and America
We landed in New York on the 12th of April, 1847, after a passage of ninety-eight days of unprecedented fair weather. The New York of 1847 was altogether a different city from the New York of 1909. It was a city of only 250,000 or 300,000 inhabitants; now it is a metropolis rivaling London in population, wealth and commerce. The whole of Manhattan Island is turned into a city of skyscrapers, churches and palatial residences.'),
  ('093a79ad-c827-5a3c-bd44-48434805a3a0', '4335dcd1-5558-5119-8672-476dd0c9f5a5', 'Based on the text, the author would most likely agree with which statement about the End-Triassic mass extinction?', '["It likely involved the extinction of more species than is typically believed.", "It is hard to detect in Earths fossil or geological records.", "It occurred over a long period of time and probably had multiple causes.", "It was discovered only recently and is poorly understood."]'::jsonb, 9, 'The End-Triassic mass extinction happened approximately 201 million years ago, when about 80 percent of species (including many species of bivalves) died off. Researchers have proposed the effects of a sudden release of carbon dioxide as one mechanism that may have brought on this mass extinction. But mass extinctions, while abrupt in geological terms, unfold over thousands or millions of years: its likely that multiple factors drove widespread species loss.'),
  ('e4d947ec-946e-5b13-9d91-f61bb745a2ec', '4335dcd1-5558-5119-8672-476dd0c9f5a5', 'According to the text, what is the subject of Bellie’s research?', '["Ocean currents", "Music history", "Space travel", "Gravitational waves"]'::jsonb, 10, 'Musician and astronomer Darsan Swaroop Bellie researches gravitational waves. These invisible waves move very quickly through space. They cannot be viewed through a telescope, but they do make sounds that can be detected with special equipment. In his musical composition Dance of the Black Holes, Bellie demonstrates what gravitational waves might sound like as two black holes merge in space. With this composition and others, Bellie hopes to make aspects of science more accessible.'),
  ('47fc8787-06ba-54ed-a71b-c27ffeaade9e', '4335dcd1-5558-5119-8672-476dd0c9f5a5', 'Based on the text, the author of Text 1 would most likely agree with the author of Text 2 on which point?', '["Capital and Ideology is notably different in structure from some of Piketty’s earlier work.", "Capital in the Twenty-First Century is a superior book to Capital and Ideology.", "The material in Capital and Ideology on The Wind Rises is essential to the book.", "Capital and Ideology was influenced by the writing of William T. Vollmann."]'::jsonb, 11, '**Text 1**:

Thomas Piketty’s book Capital in the Twenty-First Century has a more rigorous structure than its sequel, Capital and Ideology. While the first book’s chapters all contribute to bolstering a clear, coherent argument about income inequality, the second book’s digressions on subjects such as an analysis of Hayao Miyazaki’s film The Wind Rises do not just make the book tedious but also muddy its reasoning.

**Text 2**:

Capital and Ideology has different aims than Piketty’s earlier books. It should be judged not just in the context of Piketty’s previous work but placed next to books like William T. Vollmann’s Rising Up and Rising Down, in which the stated theme of justifications for violent acts is mainly an excuse for a polymath to map his own mind. Even when sections do not explicitly support the central thesis, they link to each other in intriguing ways. None of them should be considered extraneous.'),
  ('19d0def7-afdc-5fe1-b708-d8a1bf69f7a3', '4335dcd1-5558-5119-8672-476dd0c9f5a5', 'Which quotation from Memoirs of Elleanor Eldridge most effectively illustrates the claim?', '["“Let us, dear reader, remember the punishment of idle curiosity, as taught in the true and affecting history [named] ‘Blue Beard;’ and, striving to be content with the facts in the case, seek not to lift the veil, which the sensibility of true love, and feminine delicacy, have alike conspired to draw.”", "“There is often a kind of [deceptive] light, playing around such [famous] names, calculated to dazzle and mislead, by their false lustre, until the eye can no longer receive the pure light of Truth, or the mind appreciate real excellence, or intrinsic worth.”", "“Home is home, to the lowly as well as the great; and no rank, or color, destroys its sacred character, its power over the mind, and the affections.”", "“Blessed are the slumbers of the innocent! They are kindlier than balm, and they refresh and gladden the spirit of childhood, like ministerings from a better world.”"]'::jsonb, 12, 'Memoirs of Elleanor Eldridge is an 1838 historical account by Elleanor Eldridge and Frances Harriet Whipple Green. In the book, the authors assert that all people naturally have an emotional attachment to where they live, writing, _______'),
  ('50fdea37-4040-56b4-a589-367f587e3229', '4335dcd1-5558-5119-8672-476dd0c9f5a5', 'Which choice most effectively uses data from the table that weaken the student’s prediction?', '["The common snipe and the common ringed plover both have a mean body mass under 150 grams and use broken-wing display.", "The common ringed plover uses broken-wing display, but the pied-billed grebe does not.", "The pied-billed grebe has a mean body mass of 409 grams and is known to perform broken-wing display.", "The common snipe uses broken-wing display even though it is larger than the common ringed plover."]'::jsonb, 13, '**Bird Mean body mass (grams)**

| Bird | Mean body mass (grams) |
| pied-billed grebe | 409 |
| common ringed plover | 60 |
| common snipe | 126 |

One antipredator defense that the grey-headed lapwing uses to protect its nest and young chicks is called “broken-wing display”; this form of deceptive defense involves an adult bird pretending to be injured and unable to fly in order to distract an approaching predator. Broken-wing display has been documented in 285 bird species from 13 different avian orders. A student predicts that bird species with mean body masses greater than 150 grams do not use deceptive defenses because larger birds tend to be more effective than smaller birds at using aggressive defenses to protect nests from predators, making deceptive defenses unnecessary.'),
  ('751ad390-6c2d-5119-abf1-93dc057b2702', '4335dcd1-5558-5119-8672-476dd0c9f5a5', 'Which choice most logically completes the text?', '["right-handedness does not occur frequently enough among chimpanzees and squirrel monkeys to reliably appear in a sample of only 27 individuals.", "the study that did not find right-handedness in chimpanzees was also based on an insufficient population size.", "the sample size on which the claim is based is far below the threshold identified in the meta-analysis.", "the apparent difference between the two studies’ results may be partly attributable to the 1992 study using a different standard to determine handedness than the 1999 study."]'::jsonb, 14, 'Right-handedness is overwhelmingly prevalent in humans. Among studies of laterality in nonhuman primates, William C. McGrew and colleagues'' 1999 study of wild chimpanzees reported no tendency toward right-handedness, while Mara Aruguete and colleagues'' 1992 study of captive chimpanzees and squirrel monkeys did. However, the latter study included only 27 individuals, and a meta-analysis of primate-laterality studies demonstrated that a minimum sample size of 176 individuals is required to be confident that a finding of population-level handedness is not mere statistical noise. The claim of right-handedness in the 1992 study should therefore be treated skeptically given that _______'),
  ('ca387289-fc75-5a39-b119-0e692ca85a1a', '4335dcd1-5558-5119-8672-476dd0c9f5a5', 'Which choice most logically completes the text?', '["the nonmusician would play “Crazy in Love” at greater than 84.8 dB.", "the musician and nonmusician would both play other music by Beyoncé at approximately 84.8 dB.", "the nonmusician would play “Crazy in Love” at less than 84.8 dB.", "the musician would not play music in the pop genre at less than 84.8 dB."]'::jsonb, 15, 'Antonia Olivia Dolan and colleagues conducted a study of participants’ preferred listening volume, in decibels (dB), for various audio recordings, including pop music, classic rock music, and nature sounds. The team found that participants listened to recordings they liked most at higher volumes (greater dB) than recordings they liked less and that musicians tended to listen at higher volumes than nonmusicians did. For example, if the favorite recording of both a participating musician and a participating nonmusician was Beyoncé’s “Crazy in Love” and the musician played it at 84.8 dB, it was therefore likely that <u>______</u>'),
  ('ab58a85b-02bb-5bee-9529-5808e279cc2e', '4335dcd1-5558-5119-8672-476dd0c9f5a5', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["they use", "it uses", "we use", "one uses"]'::jsonb, 16, '“What stories like this do for us is make the world just a smidge bigger,” writes Stephen Graham Jones in the foreword to Never Whistle at Night: An Indigenous Dark Fiction Anthology. For Jones, dark fiction does more than entertain readers: ______ horror tropes to challenge familiar ways of knowing, blurring the “borders of the real.”'),
  ('4e2796a9-2e12-5bda-a9d8-93de0ff61bc6', '4335dcd1-5558-5119-8672-476dd0c9f5a5', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["having begun", "began", "to begin", "beginning"]'::jsonb, 17, 'Louisiana resident Caesar Antoine, one of the nearly two thousand African Americans elected to public office during the decade that followed the Civil War, ______ his term as lieutenant governor in 1873.'),
  ('aed47411-803f-5ea7-b1c2-d2408a9e550b', '4335dcd1-5558-5119-8672-476dd0c9f5a5', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["we", "it", "they", "these"]'::jsonb, 18, 'Mary Cassatt and Edith Haworth were among the 300 artists who exhibited at the 1913 Armory Show, a groundbreaking New York City art exhibition that introduced modernism to American audiences. Marcel Duchamp’s abstract cubist aesthetic received the most skepticism from critics, as _______ represented a radical departure from the more realistic painting style that was popular at the time.'),
  ('8158a517-30f2-5da1-9bd5-4a060f1d7fa6', '4335dcd1-5558-5119-8672-476dd0c9f5a5', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["has used", "uses", "is using", "use"]'::jsonb, 19, 'The International Wheelchair Basketball Federation (IWBF) is one of many sports organizations that collect and analyze data on player performance. Coaches in the IWBF _______ these data to help them develop game strategies that have a high probability of success.'),
  ('8815c84d-5257-5439-8583-a1d93be70780', '4335dcd1-5558-5119-8672-476dd0c9f5a5', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["themselves—upon fracture—", "themselves. Upon fracture,", "themselves upon fracture,", "themselves, upon fracture,"]'::jsonb, 20, 'Polymers used in industrial applications are weakened by environmental stress, mechanical fatigue, and unexpected damage. However, new types of polymers have been engineered to repair _______ aided by embedded microcapsules, such materials begin to self-heal.'),
  ('46e35981-4164-572f-b294-7a04f5781753', '4335dcd1-5558-5119-8672-476dd0c9f5a5', 'Which choice most effectively completes the text?', '["Fittingly,", "Additionally,", "Nevertheless,", "By contrast,"]'::jsonb, 21, 'Many past Olympic Games featured demonstration sports—nonmedal events—to showcase sports related to the host country. These events included sumō, a Japanese form of wrestling, and pärkspel, a Swedish ball sport. ______ they were chosen as demonstration sports at the Olympic Games in Tokyo, Japan, and Stockholm, Sweden, respectively.'),
  ('85e750c5-d8f0-5329-8567-d57c92c07f72', '4335dcd1-5558-5119-8672-476dd0c9f5a5', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["Nevertheless,", "However,", "For this reason,", "For example,"]'::jsonb, 22, 'A team led by Portuguese researcher Isabel C.F.R. Ferreira found that many species of mushrooms contain chemicals called phenolic compounds, such as protocatechuic acid and biochanin. _______ Ferreira detected protocatechuic acid in Agaricus bisporus mushrooms and biochanin in Ganoderma lucidum mushrooms.'),
  ('022969a4-f975-533c-85b5-9c227cb531d6', '4335dcd1-5558-5119-8672-476dd0c9f5a5', 'Which choice completes the text with the most logical transition?', '["Consequently,", "Nonetheless,", "As such,", "Likewise,"]'::jsonb, 23, 'In Amarna, Egypt, archaeologist Anna Hodgkinson unearthed bits of glass near lower-status dwellings, which she believes may refute the long-held notion that the material was enjoyed exclusively by Ancient Egyptian royalty. ______ archaeologist Thilo Rehren states flatly that glass doesn’t appear to have been “a closely controlled royal commodity,” concurring, based on his own research, that the material was more common than once surmised.'),
  ('be40d113-f5ed-5469-85ba-e74588d7df7c', '4335dcd1-5558-5119-8672-476dd0c9f5a5', 'The student wants to specify the average weight of the wedge-rumped storm petrel. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["The wedge-rumped storm petrel can be found on the Galápagos Island of Marchena.", "The Galápagos Islands, which include the island of Marchena, contain many different species of birds.", "Many species of birds can be found in the Galápagos Islands, including the wedge-rumped storm petrel.", "The wedge-rumped storm petrel has an average weight of 23 grams."]'::jsonb, 24, 'While researching a topic, a student has taken the following notes:

The wedge-rumped storm petrel is a species of bird.
It has an average weight of 23 grams.
It can be found on the Galápagos Island of Marchena.
The Galápagos Islands are a group of islands that have many different species of birds.'),
  ('f22d180b-13ef-5403-b4bc-96623a2701f2', '4335dcd1-5558-5119-8672-476dd0c9f5a5', 'The student wants to indicate which ecoregion the willow oak is native to. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["The willow oak is native to the Southeastern ecoregion of the US.", "The willow oak (Quercus phellos) is a species of deciduous tree.", "The willow oak’s scientific name is Quercus phellos.", "Deciduous trees are native to several ecoregions of the US."]'::jsonb, 25, 'While researching a topic, a student has taken the following notes:

The willow oak is a species of deciduous tree.
Its scientific name is Quercus phellos.
It is native to the Southeastern ecoregion of the US.'),
  ('48f48511-f697-5519-ba10-86811ca98f32', '4335dcd1-5558-5119-8672-476dd0c9f5a5', 'The student wants to explain how Charpentier describes G major. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["The key of G major is one of various keys, which are sets of musical notes that form the foundations of pieces of music.", "In Règles de Composition, Charpentier describes the mood of G major as “serious and magnificent.”", "In Règles de Composition, Charpentier describes the mood of G major.", "The song “Hero” could be described as “serious and magnificent.”"]'::jsonb, 26, 'While researching a topic, a student has taken the following notes:

In music theory, the term “key” refers to the set of musical notes that forms the foundation of a piece of music.
In Règles de Composition (1682), French composer Marc-Antoine Charpentier describes the mood of various musical keys.
He describes the key of G major as “serious and magnificent.”
“Hero” (2001) by Enrique Iglesias is a song written in G major.'),
  ('3fe26137-d9d2-5304-84e7-0b9b9a81358a', '4335dcd1-5558-5119-8672-476dd0c9f5a5', 'The student wants to make and support a claim about the inspiration for kumiko patterns. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Like the seigaiha pattern’s curved fan shapes, which resemble ocean waves, many of the geometric patterns used in kumiko designs are inspired by elements from nature.", "The kumiko woodworking technique is used to create latticed panels with geometric designs, like overlapping hexagons, out of thin strips of wood.", "The tortoiseshell-like overlapping hexagons of the kikko pattern are inspired by wooden strips from nature.", "Since kumiko relies on thin wooden strips that interlock without nails, its geometric designs—such as kikko and seigaiha—are primarily inspired by joinery techniques rather than by elements of nature."]'::jsonb, 27, 'While researching a topic, a student has taken the following notes:

Kumiko is a Japanese woodworking technique in which thin strips of wood are interlaced to create latticed panels that incorporate intricate patterns.
These wooden strips fit together without the use of nails or other fasteners.
Many of the geometric patterns used in kumiko designs are inspired by elements from nature. The overlapping hexagons of the kikko pattern resemble a tortoise’s shell.
The curved fan shapes of the seigaiha pattern resemble ocean waves.')
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('6705f07e-9910-5c71-bded-50d1b7af0faf', 1, null, '**Choice B is correct.** The sentence describes two broods whose emergences “coincided” and then calls that alignment something that “happens only once every 221 years.” The noun "convergence" precisely denotes the coming together or meeting of two things, so "a convergence that happens only once every 221 years" accurately and concisely captures the meaning implied by the coinciding emergences.
**Choice A is incorrect.** "A division" implies separation, which contradicts the idea that the broods emerged at the same time.
**Choice C is incorrect.** "An expiration" refers to ending or dying out; it does not describe two events happening simultaneously.
**Choice D is incorrect.** "A succession" implies a sequence or series occurring one after another, not the simultaneity indicated by "coincided."
**Faster approach:** Quickly match each option’s basic meaning to the key verb in the sentence (here, "coincided") and eliminate choices with opposite or unrelated senses.'),
  ('7412a677-25db-5e19-a8ee-bbe96ec7ca04', 3, null, '**Choice D is correct.** The sentence describes the National Heritage Fellowship and then gives an example of a recipient chosen "for his lifetime contributions to the arts," so the fellowship was created to recognize and celebrate outstanding artists. "Honor" precisely conveys that meaning and fits grammatically: "created to honor exceptional folk and traditional artists."
**Choice A is incorrect.** "Overshadow" means to make less noticeable or important, which contradicts the positive, recognizing function implied by the example of a chosen recipient.
**Choice B is incorrect.** "Begin" does not fit contextually or grammatically; the fellowship was created to perform an action regarding artists (recognize them), not to start them.
**Choice C is incorrect.** "Distract" is unrelated in meaning and conflicts with the respectful, celebratory tone of the passage.
**Faster approach:** Identify the passage’s tone and purpose (positive recognition) and choose the verb that matches that meaning—eliminate options with opposite or unrelated meanings.'),
  ('2deb09db-3e0b-57b6-8fa1-1791c651f144', 3, null, '**Choice D is correct.** The sentence contrasts Miyazaki’s inclusion of fantasy elements with his approach to explaining them: he presents fantastical characters with "little backstory or explanation," so he "withholds" details and exposition. "Withhold" precisely expresses holding back information, matching the passage’s description.
**Choice A is incorrect.** "Invent" means to create; the passage already states he includes fantasy elements, so inventing details would be the opposite of giving little explanation.
**Choice B is incorrect.** "Combine" means to join elements together; nothing in the sentence implies merging details or exposition.
**Choice C is incorrect.** "Celebrate" means to praise or highlight; that would suggest emphasizing details, contradicting the phrase "little backstory or explanation."
**Faster approach:** Use the immediately following phrase "with little backstory or explanation" as a context clue to pick the word meaning "hold back" (withhold) rather than any word implying creation, joining, or emphasis.'),
  ('470c4add-07ac-5c59-9a2a-1cb07278ef0d', 2, null, '**Choice C is correct.** In the phrase “of a good height,” the adjective “good” modifies “height” to indicate a relatively large or notable amount of height. In this context, “good” means appreciable or considerable — he was fairly tall. The sentence emphasizes his stature as seen even while seated, so “considerable” best captures that meaning.
**Choice A is incorrect.** “Reliable” refers to trustworthiness; nothing in the phrase or surrounding context suggests the author is describing Mr. French’s dependability.
**Choice B is incorrect.** “Courteous” describes manners or politeness, which is unrelated to a physical description of height.
**Choice D is incorrect.** “Capable” means skilled or competent; the sentence comments on physical stature, not ability, so this meaning does not fit.
**Faster approach:** When an adjective like “good” modifies a measurement word (e.g., height, size, weight), reinterpret it as “considerable” or “fairly” rather than a character trait; this quickly eliminates personal-quality choices.'),
  ('dedc4bfd-4c52-5e32-818a-06d457d39fb3', 3, null, '**Choice D is correct.** The verb "denotes" means "indicates" or "signifies," which fits the sentence: being named a City of Gastronomy denotes that Portoviejo has a unique and vibrant food culture worthy of celebration. The phrase requires a word that links the title to the meaning it conveys, and "denotes" does so precisely and formally.
**Choice A is incorrect.** "Discovers" means to find or detect; a title cannot discover something about the city, so this meaning is illogical here.
**Choice B is incorrect.** "Renounces" means to give up or reject, which contradicts the positive sense of receiving an honorific title.
**Choice C is incorrect.** "Complains" is unrelated in meaning and makes no sense in context.
**Faster approach:** Replace the blank with a simple synonym test—choose the option meaning
"indicates/signifies." This quickly eliminates choices that mean "find," "reject," or "complain."'),
  ('e2ef309f-12f6-5dc9-9b83-5563a2e58ebe', 3, null, '**Choice D is correct.** The underlined sentence characterizes what Heberling and Burke’s use of historical DNA achieves — it highlights that their approach takes advantage of a large, previously underused resource and therefore comments on the significance of that approach. The phrase "capitalizing on the research potential" directly evaluates the method’s importance rather than describing a specific result or application.
**Choice A is incorrect.** The sentence does not list specific applications or experiments enabled by the approach; it makes a general evaluative statement about research potential, not concrete uses.
**Choice B is incorrect.** The sentence does not explain reasons why the methodology is not widely used; it actually notes that the source was "relatively underutilized" but emphasizes opportunity rather than giving causal explanation.
**Choice C is incorrect.** The sentence focuses on the methodological significance of using historical DNA, not on particular findings about fungal DNA.
**Faster approach:** Look for evaluative language (e.g., "capitalizing," "research potential," "underutilized") to identify sentences that comment on significance or value; that signals a function of commentary rather than application or explanation.'),
  ('c92e32b3-3794-5fcc-af90-ffdb1bdaffbb', 3, null, '**Choice D is correct.** The underlined sentence points out that dreamers’ eye movements matched those of sighted, awake observers, and it concludes that this similarity supports the team’s claim about the brain’s perception of dream objects. That wording makes the sentence function as a comparison that justifies the researchers’ conclusion: a comparable circumstance (awake visual tracking) is used to support the inference about dreaming perception.
**Choice A is incorrect.** The sentence does not present a practical or real-world implication; it presents comparative evidence supporting a scientific conclusion rather than illustrating an application.
**Choice B is incorrect.** The sentence supports the team’s hypothesis rather than undermining it—the phrasing "suggesting" explicitly connects the observation to the conclusion.
**Choice C is incorrect.** The sentence reports a result that supports the study’s conclusion but does not indicate that the researchers changed the focus of their study.
**Faster approach:** On text-structure questions, scan for comparative language (words like "matched," "similarly," or "suggesting"); such phrasing usually signals the sentence provides evidence or an analogy that justifies a conclusion, so choose the option about providing comparable support.'),
  ('22442910-c3c1-5714-b1b1-7862c92893f6', 3, null, '**Choice D is correct.** The passage contrasts New York in 1847 with New York in 1909, emphasizing that the city has become a much larger, more developed metropolis — "rivaling London in population, wealth and commerce" and with Manhattan "turned into a city of skyscrapers, churches and palatial residences." That general statement about increased development and population is the central idea.
**Choice A is incorrect.** The passage does not discuss Yung’s personal growth; it focuses on changes in the city itself rather than his individual development.
**Choice B is incorrect.** Although the passage mentions a "passage of ninety-eight days," it does not describe the journey as tiring; instead it notes "unprecedented fair weather."
**Choice C is incorrect.** The passage compares New York to London in size, wealth, and commerce, not making a claim that New York’s architecture is more beautiful than London''s.
**Faster approach:** For main-idea questions, look for the overall topic sentence or any direct comparisons across time; choose the answer that summarizes that broad change rather than a minor detail.'),
  ('093a79ad-c827-5a3c-bd44-48434805a3a0', 2, null, '**Choice C is correct.** The passage explicitly states that although mass extinctions can seem abrupt geologically, they "unfold over thousands or millions of years" and that "it’s likely that multiple factors drove widespread species loss." Together these statements directly support the claim that the End‑Triassic extinction occurred over a long period and probably had multiple causes.
**Choice A is incorrect.** The passage gives a specific estimate (about 80 percent of species died) and does not suggest that more species went extinct than is typically believed.
**Choice B is incorrect.** The passage does not claim the extinction is hard to detect in the fossil or geological records; it discusses timing and causes, not detectability.
**Choice D is incorrect.** The passage gives a date (~201 million years ago) and discusses proposed mechanisms, so it does not say the event was discovered only recently or is poorly understood.
**Faster approach:** Read the final summary sentence(s) of the passage for the author’s main conclusion—those lines often state the timeframe and the author’s overall interpretation (here: long timeframe and multiple causes).'),
  ('e4d947ec-946e-5b13-9d91-f61bb745a2ec', 3, null, '**Choice D is correct.** The passage explicitly states that Darsan Swaroop Bellie "researches gravitational waves," so the subject of his research is gravitational waves.
**Choice A is incorrect.** The passage says nothing about ocean currents; that topic is not mentioned and therefore is not Bellie’s research subject.
**Choice B is incorrect.** Although Bellie is described as a musician, the passage does not say he researches music history; it identifies his research topic as gravitational waves.
**Choice C is incorrect.** The passage discusses space phenomena (gravitational waves and black holes) but does not describe Bellie researching space travel.
**Faster approach:** Locate the verb "researches" in the sentence naming Bellie and read the direct object that follows—this immediately identifies the research topic for any similar question.'),
  ('47fc8787-06ba-54ed-a71b-c27ffeaade9e', 0, null, '**Choice A is correct.** Text 1 states that Piketty’s earlier book, Capital in the Twenty-First Century, has "a more rigorous structure than its sequel," which directly indicates a structural difference between the two works. Text 2 likewise says that Capital and Ideology "has different aims than Piketty’s earlier books," also asserting a distinction from prior work. Both passages therefore agree that Capital and Ideology is notably different from Piketty’s earlier books.
**Choice B is incorrect.** While Text 1 implies the earlier book is superior, Text 2 defends Capital and Ideology and does not endorse a claim of overall superiority.
**Choice C is incorrect.** Text 1 calls the Miyazaki material a digression that muddies reasoning, so its author would not call it essential.
**Choice D is incorrect.** Text 2 suggests a comparison to Vollmann’s work but does not claim that Piketty was influenced by Vollmann, so Text 1 would not necessarily agree.
**Faster approach:** Scan both texts for shared keywords (e.g., "different," "sequel," "aims") to find the common claim quickly; eliminate choices that introduce unsupported judgments (influence, superiority, necessity).'),
  ('19d0def7-afdc-5fe1-b708-d8a1bf69f7a3', 2, null, '**Choice C is correct.** The claim is that “all people naturally have an emotional attachment to where they live.” Choice C directly states that “Home is home, to the lowly as well as the great; and no rank, or color, destroys its sacred character, its power over the mind, and the affections,” which explicitly asserts that everyone—regardless of status—feels a deep, emotional connection to home.
**Choice A is incorrect.** That sentence warns against idle curiosity and lifting a veil of privacy; it does not address emotional attachment to place.
**Choice B is incorrect.** That sentence criticizes fame’s deceptive allure and contrasts it with truth and intrinsic worth; it does not discuss attachment to one’s home.
**Choice D is incorrect.** While D praises innocent slumber and childhood comfort, it focuses on sleep and childhood rather than a universal emotional bond with one’s home.
**Faster approach:** Scan each quotation for explicit words about “home,” “place,” or “affection”; the choice that directly names home and universal feeling will match the claim.'),
  ('50fdea37-4040-56b4-a589-367f587e3229', 2, null, '**Choice C is correct.** The student predicts that species with mean body mass greater than 150 g do not use deceptive defenses; the table shows that the pied-billed grebe has mean body mass 409 g, and choice C states that this species is known to perform broken-wing display. That directly contradicts the prediction by providing a documented counterexample: a bird well over 150 g that uses deceptive defense.
**Choice A is incorrect.** Although it notes that the common snipe and common ringed plover are under 150 g and use broken-wing display, that information is consistent with the student’s claim (small birds using deception) and therefore does not weaken it.
**Choice B is incorrect.** Stating that the ringed plover uses broken-wing display but the grebe does not would support the prediction (larger grebe lacking deception), not weaken it.
**Choice D is incorrect.** Saying the common snipe uses broken-wing display despite being larger than the ringed plover compares two small species (126 g vs. 60 g) and does not address the student’s specific threshold (>150 g), so it does not refute the prediction.
**Faster approach:** Scan the table for any bird with mean mass >150 g and choose the answer that pairs that bird with use of deceptive defense—a direct counterexample disproves the general prediction.'),
  ('751ad390-6c2d-5119-abf1-93dc057b2702', 2, null, '**Choice C is correct.** The passage states that the 1992 study "included only 27 individuals" and that a meta-analysis found "a minimum sample size of 176 individuals is required" to be confident in population-level handedness findings; therefore the claim from the 1992 study should be treated skeptically because its sample size is far below that threshold.
**Choice A is incorrect.** The passage does not assert how frequently right-handedness occurs in those species, only that the 1992 study’s sample was small relative to the meta-analytic threshold.
**Choice B is incorrect.** The passage names the 1999 study but gives no information that its sample size was insufficient; the skepticism is directed at the small 1992 sample.
**Choice D is incorrect.** No evidence in the passage indicates the two studies used different handedness standards; the passage highlights sample-size concerns as the reason for skepticism.
**Faster approach:** Scan for numerical comparisons—match the cited sample size to the threshold given; if the study’s sample is much smaller than the required minimum, choose the answer that points to insufficient sample size.'),
  ('ca387289-fc75-5a39-b119-0e692ca85a1a', 2, null, '**Choice C is correct.** The passage reports two findings: people listen to recordings they like most at higher volumes than recordings they like less, and musicians tend to listen at higher volumes than nonmusicians. If the musician plays the shared favorite at 84.8 dB, the general tendency that musicians listen louder than nonmusicians implies the nonmusician would likely choose a lower volume for the same recording — i.e., less than 84.8 dB.
**Choice A is incorrect.** It contradicts the stated tendency that musicians listen at higher volumes than nonmusicians.
**Choice B is incorrect.** The passage makes no claim that other recordings by the same artist would be played at the same volume.
**Choice D is incorrect.** The passage does not assert an absolute floor for musicians’ listening of a genre; it only notes a relative tendency compared to nonmusicians.
**Faster approach:** Use the two comparative statements together: because musicians > nonmusicians in volume, if musician = X dB, nonmusician is likely < X.'),
  ('ab58a85b-02bb-5bee-9529-5808e279cc2e', 1, null, '**Choice B is correct.** The noun phrase that the blank replaces is "dark fiction," which is singular, so the singular pronoun and verb "it uses" correctly agree with that antecedent and produce a grammatically complete sentence: "dark fiction does more than entertain readers: it uses horror tropes to challenge..."
**Choice A is incorrect.** "They use" is a plural pronoun and verb that do not agree with the singular antecedent "dark fiction."
**Choice C is incorrect.** "We use" introduces a first-person plural subject not supported by the sentence; the sentence discusses what dark fiction does, not what the speaker and others do.
**Choice D is incorrect.** "One uses" is unidiomatic here because "one" is an impersonal pronoun and would imply a general person rather than the specific singular subject "dark fiction," so it does not match the intended meaning.
**Faster approach:** Identify the noun the blank refers to ("dark fiction") and choose the pronoun/verb form that agrees in number—singular requires "it uses."'),
  ('4e2796a9-2e12-5bda-a9d8-93de0ff61bc6', 1, null, '**Choice B is correct.** The sentence needs a finite past-tense verb to serve as the main verb of the independent clause: "Caesar Antoine ... began his term as lieutenant governor in 1873." The time marker "in 1873" signals a completed action in the past, so the simple past verb "began" is the correct form.
**Choice A is incorrect.** "Having begun" is a perfect participial phrase; it cannot function as the main verb of the independent clause and would leave the sentence without a proper finite verb.
**Choice C is incorrect.** "To begin" is an infinitive and likewise cannot serve as the main verb of the clause; it would produce an ungrammatical construction here.
**Choice D is incorrect.** "Beginning" is a present participle and would create a participial phrase, not the required simple past main verb.
**Faster approach:** Look for the time marker ("in 1873") and choose a simple past verb to express a completed past action.'),
  ('aed47411-803f-5ea7-b1c2-d2408a9e550b', 1, null, '**Choice B is correct.** The antecedent for the pronoun is "Marcel Duchamp’s abstract cubist aesthetic," a singular, inanimate noun phrase; the singular neuter pronoun "it" correctly refers back to that singular noun. The clause reads smoothly and follows standard subject–pronoun agreement.
**Choice A is incorrect.** "We" is a first-person plural pronoun and does not agree with or refer to the third-person singular antecedent "Marcel Duchamp’s abstract cubist aesthetic."
**Choice C is incorrect.** "They" is a third-person plural pronoun and would mismatch the singular antecedent.
**Choice D is incorrect.** "These" is a plural demonstrative adjective/pronoun and similarly does not agree in number with the singular noun phrase; it would suggest multiple antecedents rather than the single aesthetic.
**Faster approach:** Use pronoun-antecedent agreement: identify the noun the pronoun replaces (singular vs. plural, person, animacy) and pick the matching pronoun—here a singular, neuter form, "it."'),
  ('8158a517-30f2-5da1-9bd5-4a060f1d7fa6', 3, null, '**Choice D is correct.** The subject "Coaches" is plural, so it requires the plural verb form "use." The sentence describes a habitual action (coaches regularly analyze data to develop strategies), so the simple present "use" is the appropriate tense and number.
**Choice A is incorrect.** "Has used" is singular and present perfect; it does not agree with the plural subject "Coaches" and also implies a completed action rather than a habitual practice.
**Choice B is incorrect.** "Uses" is singular present tense and does not agree with the plural subject "Coaches."
**Choice C is incorrect.** "Is using" is present progressive and would require the plural form "are using" to agree with "Coaches." Also, the progressive suggests a temporary action rather than the habitual use implied by the context.
**Faster approach:** Use subject-verb agreement and tense: identify the plural subject and choose the plural verb in the simple present for habitual actions (here, "use").'),
  ('8815c84d-5257-5439-8583-a1d93be70780', 1, null, '**Choice B is correct.** The clause before the blank ends naturally with a complete thought (polymers have been engineered to repair themselves), so a period is appropriate. Starting a new sentence with "Upon fracture," allows the introductory phrase to modify the following clause "aided by embedded microcapsules, such materials begin to self-heal," which is grammatical: "Upon fracture, aided by embedded microcapsules, such materials begin to self-heal."
**Choice A is incorrect.** Em dashes set off an interrupter, but here they create a fractured construction that leaves the following phrase unconnected and awkward: "—upon fracture— aided by..."
**Choice C is incorrect.** Omitting internal punctuation gives "themselves upon fracture," which keeps the sentence as one long, run-on construction and fails to separate the introductory modifier properly.
**Choice D is incorrect.** Placing commas there produces a single overly complex sentence with misordered modifiers and a confusing flow; a sentence break (Choice B) is clearer and more conventional.
**Faster approach:** Look for a natural sentence boundary: if the words before the blank form a complete thought, end the sentence (use a period) and start a new one with the introductory modifier.'),
  ('46e35981-4164-572f-b294-7a04f5781753', 0, null, '**Choice A is correct.** "Fittingly" signals that the examples match expectations—sumō is a Japanese sport and pärkspel is Swedish—and so it is appropriate that they were demonstration sports at Tokyo and Stockholm, respectively. The sentence presents the examples and then notes that, as one would expect, those sports were showcased in the Olympics hosted by their countries.
**Choice B is incorrect.** "Additionally" would add another, separate piece of information, but the sentence is not introducing a new fact; it is drawing an expected connection, so "additionally" is not the right logical link.
**Choice C is incorrect.** "Nevertheless" expresses a contrast or unexpected outcome; nothing in the prior sentence sets up a contradiction, so this word is inappropriate.
**Choice D is incorrect.** "By contrast" signals an opposing example, but the second clause does not oppose the first—it reinforces that each sport was featured in its country’s Games—so this choice is wrong.
**Faster approach:** Identify the logical relationship between sentences (agreement, addition, or contrast). Then pick the transition that matches: here the examples align with the outcome, so choose the word meaning "appropriately" ("fittingly").'),
  ('85e750c5-d8f0-5329-8567-d57c92c07f72', 3, null, '**Choice D is correct.** The first sentence states a general claim that many species contain phenolic compounds and names two specific compounds; the second sentence supplies a specific instance of those compounds being detected by Ferreira, so a phrase that signals illustration—"For example,"—is appropriate. The comma correctly follows the introductory phrase.
**Choice A is incorrect.** "Nevertheless," signals a contrast or concession; nothing in the second sentence contradicts or qualifies the first sentence.
**Choice B is incorrect.** "However," also indicates contrast; the second sentence gives an example rather than opposing the claim.
**Choice C is incorrect.** "For this reason," indicates cause or consequence, which is not the relationship between the general statement and the specific example.
**Faster approach:** Identify the relationship between sentences (contrast, cause, or example) and choose the connective that matches; here the second sentence exemplifies the first, so pick "For example."'),
  ('022969a4-f975-533c-85b5-9c227cb531d6', 3, null, '**Choice D is correct.** The sentence about Rehren repeats and supports Hodgkinson’s point that glass was not limited to royalty, so a transition indicating agreement or similarity is required. "Likewise," signals that Rehren’s statement agrees with and reinforces the prior claim that glass was more common than previously thought.
**Choice A is incorrect.** "Consequently," indicates a result or consequence of the previous statement, but Rehren’s statement is independent corroboration rather than a direct consequence of Hodgkinson’s findings.
**Choice B is incorrect.** "Nonetheless," signals contrast or concession, which conflicts with the fact that Rehren’s comment concurs with Hodgkinson rather than contradicting it.
**Choice C is incorrect.** "As such," means "because of that" or "in that role," which mislinks the ideas here; Rehren is providing corroboration, not drawing a conclusion that follows directly from the preceding clause.
**Faster approach:** For transition questions, identify whether the second sentence agrees, contrasts, or shows a result; pick a transition word that matches that relation (agreement → likewise/also; contrast → however/nonetheless; result → consequently/as a result).'),
  ('be40d113-f5ed-5469-85ba-e74588d7df7c', 3, null, '**Choice D is correct.** It directly states the specific information the student wants: the wedge-rumped storm petrel’s average weight is 23 grams. This choice uses the relevant note verbatim and is clear, specific, and concise.
**Choice A is incorrect.** Although it correctly reports the petrel’s location on Marchena, it says nothing about the bird’s weight and therefore does not accomplish the student’s goal.
**Choice B is incorrect.** This sentence summarizes information about the Galápagos Islands and their bird diversity but does not provide the petrel’s average weight.
**Choice C is incorrect.** While it mentions that the petrel is among many Galápagos birds, it does not specify the petrel’s weight and thus fails to answer the student’s specific need.
**Faster approach:** Scan the notes for the sentence that explicitly contains the requested fact (here, the note that states the weight) and choose that sentence directly.'),
  ('f22d180b-13ef-5403-b4bc-96623a2701f2', 0, null, '**Choice A is correct.** It directly states that the willow oak is "native to the Southeastern ecoregion of the US," which uses the relevant note about its native ecoregion to answer the student’s goal succinctly and precisely.
**Choice B is incorrect.** Although it correctly identifies the willow oak as a deciduous tree and gives the scientific name, it does not indicate which ecoregion the species is native to.
**Choice C is incorrect.** Stating the scientific name provides taxonomic information but does not address the question about the tree’s native ecoregion.
**Choice D is incorrect.** This general statement about deciduous trees does not specify that the willow oak is native to the Southeastern ecoregion and is therefore not relevant to the student’s goal.
**Faster approach:** Pick the option that directly repeats the ecoregion information from the notes; answers that generalize or give other facts are irrelevant.'),
  ('48f48511-f697-5519-ba10-86811ca98f32', 1, null, '**Choice B is correct.** It directly reports how Charpentier characterizes G major by naming the source and providing the quoted description: “serious and magnificent,” which exactly answers the student’s goal of explaining Charpentier’s description.
**Choice A is incorrect.** It defines what a key is but does not say how Charpentier describes G major, so it fails to accomplish the stated goal.
**Choice C is incorrect.** Although it notes that Charpentier describes the mood of G major, it omits the actual description and therefore does not explain how he describes it.
**Choice D is incorrect.** It speculates about the song “Hero” rather than reporting Charpentier’s description of the G major key, so it does not address the student’s objective.
**Faster approach:** Look for the choice that names the source and includes the specific quoted description—answers that both identify the source and give the exact wording will directly satisfy a prompt asking how someone describes something.'),
  ('3fe26137-d9d2-5304-84e7-0b9b9a81358a', 0, null, '**Choice A is correct.** The notes directly state that "many of the geometric patterns used in kumiko designs are inspired by elements from nature," and they give seigaiha ("curved fan shapes...resemble ocean waves") as an example. Choice A restates the general claim and uses a specific example from the notes to support it, so it most effectively makes and supports the intended claim.
**Choice B is incorrect.** It describes how kumiko is made (latticed panels from thin strips), but it does not make or support a claim about the inspiration for the patterns.
**Choice C is incorrect.** It misrepresents the notes by claiming the kikko pattern is "inspired by wooden strips from nature," whereas the notes say the kikko pattern resembles a tortoise’s shell — an animal, not wooden strips.
**Choice D is incorrect.** It contradicts the explicit note that many kumiko patterns are inspired by elements from nature and instead attributes the designs primarily to joinery techniques; that claim is not supported by the provided notes.
**Faster approach:** Look for the sentence that directly states the general claim in the notes and choose the answer that pairs that general statement with one of the specific examples given.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;

-- PeaklyTest Oct 2025 · Reading & Writing · Module 2
insert into public.tests (id, title, section, description, duration_min, position, published, form_title, module_no)
values ('73cf644a-a325-5e9b-9141-f160d1ae4244', 'PeaklyTest Oct 2025 · Reading & Writing · Module 2', 'Reading & Writing', 'Reading & Writing, Module 2 of the Oct 2025 PeaklyTest · 27 questions · 32 minutes', 32, 181, true, 'PeaklyTest Oct 2025 · Reading & Writing', 2)
on conflict (id) do update set title = excluded.title, section = excluded.section, description = excluded.description,
  duration_min = excluded.duration_min, position = excluded.position, form_title = excluded.form_title, module_no = excluded.module_no;
insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('ef170468-058b-5b13-b12c-4bb84222966c', '73cf644a-a325-5e9b-9141-f160d1ae4244', 'Which choice completes the text with the most logical and precise word or phrase?', '["abrasive", "outspoken", "opaque", "ambivalent"]'::jsonb, 1, 'Players of online games are largely aware that the games collect their data, and they’re often willing to trade some privacy for a fun experience. But the games are often quite _______ about what data they collect and why. Because of this, data-privacy advocates are seeking to expand online players’ knowledge of data collection practices and improve their ability to navigate privacy-setting features in games.'),
  ('724117d8-10ff-50e9-81d1-3aaa153a44f8', '73cf644a-a325-5e9b-9141-f160d1ae4244', 'Which choice completes the text with the most logical and precise word or phrase?', '["prompted by", "excluded by", "released in", "acknowledged in"]'::jsonb, 2, 'Microbiologist Radames Cordero and team investigated surface temperatures of a variety of fungi, including Amanita brunnescens and a species from the genus Hortiboletus, in a study ______ a previous observation: Cordero had taken thermal images of various wild mushrooms while hiking and found that the mushrooms all appeared to be colder than the surrounding environment, raising questions about thermoregulation in fungi.'),
  ('157a4863-701a-53d2-8e88-fb323640d87f', '73cf644a-a325-5e9b-9141-f160d1ae4244', 'As used in the text, what does the word “betraying” most nearly mean?', '["Exploiting", "Exposing", "Forsaking", "Distorting"]'::jsonb, 3, 'The following text is from Edward Gibbon’s 1796 Memoirs of My Life and Writings. Gibbon reflects on publishing a volume of his series The History of the Decline and Fall of the Roman Empire.

I am at a loss how to describe the success of the work, without <u>betraying</u> the vanity of the writer. The first impression was exhausted in a few days; a second and third edition were scarcely adequate to the demand.'),
  ('ca3fc950-e90b-54f2-8405-adfb45b5b701', '73cf644a-a325-5e9b-9141-f160d1ae4244', 'Which choice completes the text with the most logical and precise word or phrase?', '["inevitable", "extemporaneous", "inconspicuous", "meticulous"]'::jsonb, 4, 'Described in treatises mainly published between 1768 and 1950 (such as W.D. Dunton’s Dunton’s Musical Shorthand), musical stenography used quickly written squiggles and dots in an attempt to preserve, in print and in real time, the ______ features of live performances—those that result from impromptu deviations of performers when fidelity to an established musical score is not mandated.'),
  ('20c801b0-967c-59fb-ba42-6233cc174d2e', '73cf644a-a325-5e9b-9141-f160d1ae4244', 'Which choice best states the main purpose of the text?', '["To explain that a particular painting by Harold Newton has had greater influence on the broader culture of the state of Florida than is generally acknowledged", "To contrast the public’s reaction during the 1950s and ’60s to a particular painting by Harold Newton with more recent reactions to it", "To describe the historical circumstances in which paintings by the Florida Highwaymen experienced a resurgence in popularity", "To present the argument that paintings by the Florida Highwaymen likely helped to create a particular widespread impression of Florida."]'::jsonb, 5, 'Harold Newton’s Yellow Day, a wetland landscape with palm trees and lush greenery set against the pastel yellows and pinks of the sky and water, is typical of paintings by the Florida Highwaymen, loosely affiliated landscape artists mainly active in Fort Pierce, Florida, during the 1950s and ’60s. Some art historians suggest that Highwaymen paintings played a role in shaping popular perceptions of the state that persist today: the natural iconography that Newton and colleagues constantly revisited—lush tropical forests, vivid sunsets—is now seen as classically Floridian.'),
  ('b33146c1-85c4-5c91-bada-be3b0d8253ad', '73cf644a-a325-5e9b-9141-f160d1ae4244', 'Which choice best describes the overall structure of the text?', '["The text names projects that are noteworthy for their inclusion of certain materials and then explains past important uses of the materials.", "The text introduces the salient characteristics of two buildings and then details the historical events that occasioned the buildings’ designs.", "The text cites examples of a design trend and then briefly establishes the principles underlying the trend.", "The text distinguishes between two aesthetic approaches to architecture and then submits that one approach has had more of a long-term impact than the other has had."]'::jsonb, 6, 'The metal featured in both the structure of the Shimogamo Machiya Villa by Takuma Ohira and the hardware in the One-Room Residence of 5 Layers by Matsuyama Architect and Associates is representative of a trend in contemporary Japanese interior design to juxtapose sleek, modern accents with traditional organic materials such as cypress. The prominent feature of metal stems from the post–World War II emphasis on technological progress, while more traditional natural materials help preserve longstanding architectural and aesthetic approaches.'),
  ('09ae98ee-953e-5e59-b961-bdf0cf56cd77', '73cf644a-a325-5e9b-9141-f160d1ae4244', 'Based on the texts, how would Rose and colleagues (Text 2) most likely respond to the assertion by Slater and Mann (Text 1) about the different prevalence of female birdsong in temperate and tropical areas?', '["They would raise the possibility that the difference in prevalence may be due to differences in the timing of the mating season among temperate and tropical bird species.", "They would concede that the geographic difference in prevalence is real but argue that the frequency with which male tropical birds sing has been overstated by previous researchers.", "They would argue that the apparent difference in prevalence may partly reflect a difference in the ease with which female birdsong and male birdsong can be detected.", "They would propose that female birds in temperate areas sing more frequently than previously thought due to evolving environmental changes."]'::jsonb, 7, '**Text 1**:
For decades, ornithologists assumed that if they saw a singing house wren—a bird species found in temperate North America—they must be observing a male trying to attract a mate or claim territory. As Peter J.B. Slater and Nigel I. Mann have emphasized, however, a similar assumption can’t be made about birds in the tropics, where females sing as often as males do. Slater and Mann call for more research on this discrepancy between tropical and temperate female birdsong.

**Text 2**:

Recent evidence shows that a female house wren is as capable of song as a male is. In fact, female birdsong is more common among temperate species than currently assumed, claim Evangeline Rose and colleagues. These female songbirds sing less frequently than males do, and in duller tones, making it "easy for researchers to miss the quiet and hidden females and focus on the loud and colorful males," says Rose.'),
  ('aa58aa47-da55-5fc6-87c9-e24b8357f9a6', '73cf644a-a325-5e9b-9141-f160d1ae4244', 'Which choice most effectively uses data from the table to complete the comparison?', '["construction and nearly equal to transportation/warehousing and wholesale trade.", "both construction and wholesale trade but below transportation/warehousing.", "transportation/warehousing, wholesale trade, and construction.", "construction but below both transportation/warehousing and wholesale trade."]'::jsonb, 8, '**Impact of Four Key Industries on Oklahoma Economy in 2017**

| Industry | Approximate total contribution by industry | Number of people employed by industry | Average contribution per employee by industry |
| Wholesale trade | \$10,723,400,000 | 58,346 | \$183,79 |
| Construction | \$6,797,300,000 | 77,247 | \$87,99 |
| Tribal economic activity | \$7,312,400,000 | 51,674 | \$141,51 |
| Transportation/warehousing | \$12,414,600,000 | 52,891 | \$234,72 |

The nearly forty tribes located in Oklahoma, including the Cherokee Nation and the Seminole Nation, operate numerous businesses and generate billions of dollars in revenue. A student in an economics class is researching the tribes’ collective activity as a single industry. The student wants to compare that industry’s contribution to Oklahoma’s overall economy in 2017 with the contributions made by three other industries in the state. Looking at the table, the student finds that tribal economic activity totaled over \$7.3 billion, ranking it above ______.'),
  ('11870692-31b3-5c04-9f81-8bb0cb97278a', '73cf644a-a325-5e9b-9141-f160d1ae4244', 'Which choice most effectively uses data from the table to complete the statement?', '["humans’ responses to pupil size in other people may extend to dogs, as participants responded more positively to images of dogs whose iris colors were likely to make their pupils appear larger than they did to images of dogs whose iris colors were unlikely to have that effect.", "iris color in domestic dogs may be an adaptation to elicit positive responses from humans, as participants responded more negatively to images of dogs whose iris colors can make pupils appear large than they did to images of dogs without such iris colors.", "differences in dogs’ pupil size may elicit a stronger response in humans than differences in people’s pupil size do, as participants’ responses to the images when dogs’ pupils were smaller than average were more positive than they were to images when dogs’ pupils were larger than average.", "Participants responded more positively to images of dogs with light irises than to those with dark irises, suggesting that iris colors making pupils appear smaller elicit more favorable reactions."]'::jsonb, 9, '| Image ID number | Irises | Not friendly (0)–Friendly (5) | Immature (0)– Mature (5) | Would not keep (0)–Would keep (3) | Would not interact with (0)–Would interact with (3) |
| 24 | light | 2.67 | 4.03 | 1.4 | 1.7 |
| 14 | light | 2.11 | 3.27 | 1.55 | 1.85 |
| 6 | dark | 4.03 | 2.95 | 1.85 | 1.65 |
| 3 | dark | 3.88 | 2.51 | 2.35 | 2.65 |

Studies have found that when looking at other people’s eyes, humans tend to perceive dilated pupils positively and constricted pupils negatively. Noting that a dark iris—the colored portion surrounding the pupil—is hard to distinguish from the black of the pupil (and thereby affects the pupil’s apparent size) and that many domestic dogs have dark irises, Akitsugu Konno et al. showed close-up images of dogs’ faces to human participants and asked them to rate the dogs’ traits and their own attitudes toward the dogs. Their findings suggest that ____.'),
  ('b05336e4-994f-5887-9c50-5b2227a909bd', '73cf644a-a325-5e9b-9141-f160d1ae4244', 'Which finding from the study, if true, would most directly support the text’s characterization of the study’s results?', '["Although only 15 instances of co-occupation of unmanipulated boxes by wasps and birds were observed over the course of the study, in a majority of those instances, wasps were already occupying the boxes when birds initiated nesting in them.", "Wasps initiated nesting in manipulated boxes much more often than in unmanipulated boxes, and 80% of initial co-occupations of unmanipulated boxes resulted in abandonment by wasps but not by birds.", "Even though overall usage of the nesting boxes by wasps and birds was high throughout the study, 24% of the manipulated boxes remained vacant each spring, while less than 4% of the unmanipulated nesting boxes remained vacant.", "Co-occupation was rare because chickadees and paper wasps nested at different times of the season, with little overlap; in the few overlaps observed, persistence rates were similar for both species."]'::jsonb, 10, 'Carolina chickadees are cavity nesting birds that initiate nest building at the same time of year as golden paper wasps, a species that also nests in enclosed spaces. Researchers observed that both species will settle in nesting boxes, but birds and wasps are not often observed co-occupying boxes, leading to the hypothesis that the two species compete for nesting sites. To test this hypothesis, the researchers installed nesting boxes throughout a nature preserve in the US state of North Carolina, manipulated some of the boxes to exclude birds, and then monitored the boxes for two years. Not only was the hypothesis validated, there was also a clear indication of competitive advantage for birds.'),
  ('0e01e10b-bd8c-51ac-85ba-a1483a13b6ca', '73cf644a-a325-5e9b-9141-f160d1ae4244', 'Which finding about the Cairo site, if true, would most directly support Khudadad’s conclusion?', '["The site appears to have been a tropical deltaic forest early in the Devonian period but transitioned to an arid floodplain forest after the end of the Devonian period.", "Fossil evidence from the site suggests that several forest plant species other than Eospermatopteris and Archaeopteris lived there during the Devonian period.", "Although the site appears to have been a tropical deltaic forest during the Devonian period, fossil evidence suggests that Eospermatopteris was present at that time.", "The site appears to have been an arid floodplain forest during the Devonian period and contains fossil evidence of both Eospermatopteris and Archaeopteris."]'::jsonb, 11, 'Based on findings from fossil sites, paleobotanists had developed the so-called partition hypothesis, which holds that there were two distinctly different kinds of biomes during the Devonian period (circa 360 to 420 million years ago). One was a tropical deltaic forest biome home to plants such as the fernlike Eospermatopteris, and the other was an arid floodplain forest biome home to plants such as the coniferlike Archaeopteris. Recently, however, evolutionary ecologist Khudadad Khudadad examined the remnants of a Devonian forest in what is now Cairo, New York, and concluded that evidence from the Cairo site is inconsistent with the partition hypothesis.'),
  ('3bcfdc11-068a-5d25-96a0-689c7bad7b33', '73cf644a-a325-5e9b-9141-f160d1ae4244', 'Which finding, if true, would most directly challenge the second research team’s conclusion?', '["The study by Oguchi and colleagues had a low detail rating and a low traceability rating.", "The study by Feehan and Kandlikar had a lower traceability rating than the study by Oguchi and colleagues did.", "The study by Feehan and Kandlikar had a high detail rating and a high traceability rating.", "The study by Feehan and Kandlikar had a lower detail rating than the study by Oguchi and colleagues did."]'::jsonb, 12, 'Callie W. Babbitt, Hema Madaka, and colleagues assembled a database of materials used in consumer electronics by studying products in the lab and by gathering data from similar product studies. The team gave each of these studies a rating for level of detail (with a higher rating for reported data with more detail) and for level of traceability (with a higher rating for clearer descriptions of procedures). Based on these ratings, a second research team concluded that a study by Paul Feehan and Milind Kandlikar provided more specificity in its data than a study by Oguchi Masahiro and colleagues did.'),
  ('5e6022b3-b794-5800-8915-423f53b0a808', '73cf644a-a325-5e9b-9141-f160d1ae4244', 'Which choice most logically completes the text?', '["differences in oil import-export ratios from one country to another may account for more of the differences in the effects of oil shocks on those countries'' economies than economists previously believed.", "methodological discrepancies in studies of oil shocks may have contributed to economists'' inability to provide a generalized model of oil shocks'' effects on national economies.", "economists'' conventional measures of national economic activity may be insufficiently sensitive to the effects of oil shocks.", "controlling for variations in countries'' oil import-export ratios might not resolve the difficulties economists have had in constructing a broadly applicable description of oil shocks'' effects."]'::jsonb, 13, 'In 1990, oil prices rose 90% between August and October, creating what economists term an oil shock. Although oil shocks have occurred multiple times since 1945, a broadly applicable description of how oil shocks affect economies at the national level has proved elusive, a problem typically attributed to the fact that oil shocks'' effects are substantially conditioned on country-specific characteristics (oil import-export ratios, most importantly). Recently, however, Gbadebo Oladosu et al. showed that economists'' estimates of national economies'' responsiveness to oil shocks are highly heterogeneous even within a given country and time frame—ranging by more than a factor of five in the case of Australia during a recent oil shock, for instance—suggesting that __________'),
  ('2a060526-faac-501e-98eb-b8abe591054e', '73cf644a-a325-5e9b-9141-f160d1ae4244', 'Which choice most logically completes the text?', '["the new piece of furniture is less appealing to college students than other similar products on the market are.", "college students might be more likely than participants in the other demographic groups to purchase the piece of furniture.", "college students likely prioritize other factors over a product’s environmental sustainability when making purchasing decisions.", "there is not a meaningful difference in the average likelihood of purchasing environmentally friendly products among the demographic groups included in the study."]'::jsonb, 14, 'Saeed M.Z.A. Tarabien conducted a study of consumer attitudes toward Jordanian food and beverage companies and found that for consumers who value environmental conservation, their likelihood of purchasing a product decreased when their perception of the product’s risk of causing environmental harm increased. Subsequently, other researchers conducted a study of various demographic groups in China, investigating participants'' intentions to purchase a new piece of furniture, and found that, on average, college students had the lowest perception among all the demographic groups in the study of the environmental risks of the piece of furniture. Assuming that the results of Tarabien’s study are broadly applicable, this finding suggests that ______.'),
  ('5295e6b2-5798-5c85-8197-a357a7f7d605', '73cf644a-a325-5e9b-9141-f160d1ae4244', 'Which choice most logically completes the text?', '["listeners who use streaming services would be more likely to give physical copies of music as gifts to others than to purchase physical copies for themselves.", "listeners who prefer to purchase compact discs rather than use a service such as Bandcamp or Tidal would tend to listen to older music.", "the music choices of listeners who use streaming services would likely be more varied than those of listeners who do not use streaming services.", "music publishers who choose to forgo releasing music on physical media are likely to see no change in revenue."]'::jsonb, 15, 'The advent of online streaming has led many music listeners to drift away from ownership of music (through downloads or through physical media such as compact discs) and toward the streaming services Bandcamp and Tidal, among others. Datta et al. studied the impact of this change on the variety of music that listeners consume. The researchers reasoned that the ownership model of music assigns a cost per song to acquiring a variety of music, while streaming services typically charge a flat fee for access to an entire music catalog, making variety free, which suggests that ______.'),
  ('5e911747-788a-5417-a27f-6e0246e5e671', '73cf644a-a325-5e9b-9141-f160d1ae4244', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["largely occurring", "largely occur", "have largely occurred", "is largely occurring"]'::jsonb, 16, 'In a letter dated January 14th, 1780, congressman John Witherspoon attempts to persuade General George Washington that the Continental Army’s difficulty in procuring supplies, often attributed to disloyalty among civilian farmers and merchants, ______ due to concerns suppliers have about receiving compensation in the form of rapidly depreciating Continental currency.'),
  ('3188d878-b3a8-5418-ad92-4daa2649c2f8', '73cf644a-a325-5e9b-9141-f160d1ae4244', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["concern, though;", "concern: though", "concern, though", "concern, though:"]'::jsonb, 17, 'Social media platforms have made the collection of qualitative human behavioral data easier than ever. To collect such data by means of social media does raise a serious ethical ______ terms of service stipulate that platforms can analyze users’ accounts and posts, according to sociologist Jose van Dijck, users are not informed when their data are included in behavioral studies.'),
  ('24443e80-7628-5ed5-a8cc-9a4b798acb56', '73cf644a-a325-5e9b-9141-f160d1ae4244', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["are paving", "is paving", "have paved", "paving"]'::jsonb, 18, 'The neurotechnology company MindMaze is working on an exciting new technology: game-based digital therapies that improve neuroplasticity to help with cognitive rehabilitation. MindMaze’s technology, alongside other such neuromodulation technologies that function by stimulating nervous system structures, ______ the way for future advancements in neurotechnology.'),
  ('af85e56d-5c99-52f5-aaaa-ff8363a95187', '73cf644a-a325-5e9b-9141-f160d1ae4244', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["swimming is", "swimming has been", "swimming, is", "swimming,"]'::jsonb, 19, 'Helical ______ widely understood to confer stability and efficiency in the locomotion of a variety of microscopic organisms—including bacteria, eukaryotic algae, and ciliates—bestows similar advantages, albeit via different propulsive modes, to larger oceanic macroplanktons, such as salps.'),
  ('be8bd220-5b3b-5672-9416-24ca870d2a8d', '73cf644a-a325-5e9b-9141-f160d1ae4244', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["Belgravia, published", "Belgravia published", "Belgravia; published", "Belgravia. Published"]'::jsonb, 20, 'Alberto Gabriele, author of Reading Popular Culture in Victorian Print, tracks the transnational dissemination of works by author Mary Elizabeth Braddon via the magazine _________ from 1866 to 1899 and distributed throughout the Australian cities of Melbourne, Adelaide, and Hobart; the continental European cities of Brussels, Paris, and Turin; and cities in Turkey, India, and Jamaica, this magazine helped make Braddon’s serialized novels globally available.'),
  ('5eddf112-8502-5efc-94b3-3bfe44afab47', '73cf644a-a325-5e9b-9141-f160d1ae4244', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["1906—roughly six weeks earlier. Page''s", "1906. Roughly six weeks earlier, Page''s", "1906 roughly six weeks earlier, Page''s", "1906—roughly six weeks earlier—Page''s"]'::jsonb, 21, 'Brothers Orville and Wilbur Wright famously received a patent for their flying machine on May 22, 1906. Louisiana native Charles F. Page, who was born into slavery and self-educated, created a gas-powered flying ship in 1903 that was officially patented on April 10, __________ only model had been suspiciously destroyed en route to a planned demonstration at the 1904 World’s Fair, and, discouraged, he never built a replacement.'),
  ('7fc30669-6164-5d9b-acbf-a67478216585', '73cf644a-a325-5e9b-9141-f160d1ae4244', 'Which choice completes the text with the most logical transition?', '["Conversely,", "In other words,", "However,", "Then,"]'::jsonb, 22, 'In contrast to first-past-the-post electoral processes, the proportional representation system by which Paraguay’s Chamber of Senators is elected begins with citizens casting their votes not for specific candidates but for political parties. __________ once the votes have been tabulated, each party is awarded a number of seats proportional to the number of votes it received.'),
  ('b7f81566-4f43-579e-b5eb-aa8ef4f7517b', '73cf644a-a325-5e9b-9141-f160d1ae4244', 'Which choice completes the text with the most logical transition?', '["As a result,", "On the contrary,", "That said,", "In addition,"]'::jsonb, 23, 'At Storm King Art Center, an outdoor sculpture park in New York, Herbert Ferber’s Konkapot II is exposed to rain, snow, heat, and humidity. _________ it remains in good condition due to its material: Ferber’s sculpture is made of corrosion-resistant steel.'),
  ('4b9230a9-01d1-5869-8441-4e9f588f8be7', '73cf644a-a325-5e9b-9141-f160d1ae4244', 'Which choice completes the text with the most logical transition?', '["Specifically,", "For example,", "Sometimes,", "Accordingly,"]'::jsonb, 24, 'A writer whose debut novel is a success may struggle to live up to that first book’s promise. _________ as in the case of Tommy Orange, author of the popular debut There There (2018) and the sequel Wandering Stars (2024), the follow-up actually elevates the writer’s reputation. (Wandering Stars was labeled a "towering achievement" by the New York Times.)'),
  ('c2e20b2d-0cc5-5fc7-8ea5-0b905349be0c', '73cf644a-a325-5e9b-9141-f160d1ae4244', 'Which choice completes the text with the most logical transition?', '["In conclusion,", "As such,", "However,", "In addition,"]'::jsonb, 25, 'Photogrammetry and boolean modeling approaches to three-dimensional digital modeling for video games yield graphics that accurately represent the relative sizes and proportions of real-world objects, but since these graphics are rendered from perfect geometric shapes, they tend to lack organic realism. _________ these 3D elements may display unnaturally precise angles and curves as compared to their real-world counterparts.'),
  ('a25b3e7e-ee57-55d3-8648-cadcc441dd6f', '73cf644a-a325-5e9b-9141-f160d1ae4244', 'The student wants to contrast the locations of the two specimens. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Raymond is housed at the National Museum of Nature and Science in Tokyo, Japan, while Dio is housed at the Royal Ontario Museum in Ontario, Canada.", "Like Raymond, Dio is a Triceratops fossil specimen that lived in the Late Cretaceous period.", "The Triceratops fossil specimen Raymond is not the only such specimen currently housed in a museum or institute.", "The Royal Ontario Museum in Ontario, Canada, houses Dio."]'::jsonb, 26, 'While researching a topic, a student has taken the following notes:

Raymond is the nickname of a Triceratops fossil specimen housed at the National Museum of Nature and Science.
The National Museum of Nature and Science is located in Tokyo, Japan.
Raymond lived in the Late Cretaceous period.
Dio is the nickname of a Triceratops fossil specimen housed at the Royal Ontario Museum. The Royal Ontario Museum is located in Ontario, Canada.
Dio lived in the Late Cretaceous period.'),
  ('b39dfbf8-20cf-5587-8dce-4c9748ded96d', '73cf644a-a325-5e9b-9141-f160d1ae4244', 'The student wants to explain why Manchu is classified as a synthetic language. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Manchu is classified as a synthetic language, meaning that the Tungusic language utilizes nouns to fulfill various functions within a sentence.", "Manchu is a synthetic language rather than an analytic language, where nouns rely on word order and auxiliary words to indicate their function.", "Manchu has a robust case system in which nouns take different forms depending on their function, making it a synthetic language.", "Manchu is classified as synthetic because it indicates noun function mainly through word order and auxiliary words; for example, boode uses the separate word de to mean “in the house.”"]'::jsonb, 27, 'While researching a topic, a student has taken the following notes:

Manchu is a synthetic language in the Tungusic language family.
In synthetic languages, nouns can take several different forms (or cases) depending on their function within a sentence.
Combining the suffix -de with the Manchu noun boo (house) forms the locative-case noun boode (in the house).
Synthetic languages have extensive case systems.
In analytic languages, cases are not typically used to indicate noun function.
Noun function is instead indicated through word order and auxiliary words (such as prepositions and adjectives).')
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('ef170468-058b-5b13-b12c-4bb84222966c', 2, null, '**Choice C is correct.** The passage contrasts players'' awareness of data collection with the games'' lack of clarity about those practices; the phrase that best captures that lack of clarity is "opaque," meaning not transparent or hard to understand. This fits the subsequent sentence about advocates trying to expand knowledge and improve navigation of privacy settings.
**Choice A is incorrect.** "Abrasive" means harsh or irritating; that does not relate to clarity about what data are collected and why.
**Choice B is incorrect.** "Outspoken" means candid or frank, which would imply transparency rather than the secrecy the passage describes.
**Choice D is incorrect.** "Ambivalent" means having mixed feelings; that describes attitudes, not the games'' level of transparency.
**Faster approach:** Look for a word that contrasts with "expand knowledge" and "improve ability"—choose the word meaning "not clear/transparent" (opaque).'),
  ('724117d8-10ff-50e9-81d1-3aaa153a44f8', 0, null, '**Choice A is correct.** The sentence describes researchers following up on an earlier finding: Cordero had observed that mushrooms appeared colder than their surroundings, and the team then "investigated" that phenomenon. "Prompted by" precisely expresses that the previous observation motivated the new study, making the clause logically and syntactically correct.
**Choice B is incorrect.** "Excluded by" would mean the study left out the previous observation or eliminated it, which contradicts the described follow-up relationship.
**Choice C is incorrect.** "Released in" implies the previous observation was published at a certain time, but the sentence needs a phrase indicating motivation, not publication timing.
**Choice D is incorrect.** "Acknowledged in" suggests the study merely noted the earlier observation, not that the observation motivated or prompted the investigation; it weakens the causal relationship implied by the context.
**Faster approach:** Identify whether the blank should show causation (motivated the study), timing, exclusion, or mere mention; choose the verb phrase that expresses motivation—"prompted by"—for follow-up studies.'),
  ('157a4863-701a-53d2-8e88-fb323640d87f', 1, null, '**Choice B is correct.** In the sentence Gibbon worries that describing the success of his work will "betray the vanity of the writer," meaning it will reveal or make evident his pride. The context—concern about how to speak of success without showing personal pride—fits the sense "expose."
**Choice A is incorrect.** "Exploiting" means taking advantage of something for gain; that sense does not match Gibbon’s worry about showing personal vanity.
**Choice C is incorrect.** "Forsaking" means abandoning or giving up, which is unrelated to revealing or showing a trait.
**Choice D is incorrect.** "Distorting" means misrepresenting or twisting; Gibbon is concerned about revealing vanity, not about misrepresenting the success.
**Faster approach:** For words in context, substitute concise synonyms that fit the sentence meaning and tone; here "expose/reveal" immediately preserves the sense and fits the context.'),
  ('ca3fc950-e90b-54f2-8405-adfb45b5b701', 1, null, '**Choice B is correct.** The passage describes features that arise from “impromptu deviations” by performers when strict adherence to a score is not required; “extemporaneous” means improvised or done without preparation, which precisely matches those spontaneous qualities of live performance.
**Choice A is incorrect.** “Inevitable” means unavoidable; the passage does not claim these features must happen, only that they result when performers deviate, so inevitability is too strong and not supported by the context.
**Choice C is incorrect.** “Inconspicuous” means not easily seen; the passage is focused on the nature (improvised quality) of the features, not on their noticeability, so this is irrelevant and imprecise.
**Choice D is incorrect.** “Meticulous” means very careful and precise, which contradicts the idea of spontaneous, impromptu deviations and thus does not fit the passage.
**Faster approach:** Substitute each choice into the sentence and pick the one that is a direct synonym of “impromptu” or “improvised”; that quickly isolates “extemporaneous.”'),
  ('20c801b0-967c-59fb-ba42-6233cc174d2e', 3, null, '**Choice D is correct.** The passage summarizes a claim by art historians that the recurring natural imagery in Florida Highwaymen paintings “likely helped to create a particular widespread impression of Florida” — namely, that lush forests and vivid sunsets are classically Floridian. The passage focuses on that argument rather than on detailed history or reactions.
**Choice A is incorrect.** The passage does not claim Newton’s single painting had greater influence than generally acknowledged; it speaks generally about Highwaymen paintings and presents historians’ suggestions, not a corrective claim about recognition.
**Choice B is incorrect.** No comparison of public reactions from the 1950s–60s to more recent reactions appears in the text.
**Choice C is incorrect.** The passage does not describe historical circumstances or a resurgence in popularity; it only notes the imagery’s influence on perceptions.
**Faster approach:** For main-purpose questions, paraphrase the sentence that states the author’s central claim (often the concluding sentence); choose the answer that matches that paraphrase.'),
  ('b33146c1-85c4-5c91-bada-be3b0d8253ad', 2, null, '**Choice C is correct.** The passage first mentions two specific projects that exemplify a broader design practice (metal in the Shimogamo Machiya Villa and One‑Room Residence) and then offers brief explanations for that practice (metal reflects post–World War II emphasis on technological progress; natural materials preserve longstanding approaches). This is exactly the structure of giving examples followed by the principles or causes underlying the trend.
**Choice A is incorrect.** Although the passage names projects and mentions materials, it does not primarily "explain past important uses of the materials"; it explains reasons behind the current trend, not a history of past uses.
**Choice B is incorrect.** The passage does not detail historical events that occasioned the buildings’ designs in any depth; it gives one causal explanation (post–World War II emphasis) rather than detailing the buildings’ designs themselves.
**Choice D is incorrect.** The passage does compare modern accents and traditional materials, but it does not argue that one approach had more long‑term impact; it states complementary roles rather than asserting greater impact.
**Faster approach:** Look for the sequence: identify whether the passage gives examples first and then explains causes/principles (choose C), or explains then supports with examples—this pattern quickly matches the correct answer for text‑structure questions.'),
  ('09ae98ee-953e-5e59-b961-bdf0cf56cd77', 2, null, '**Choice C is correct.** Rose and colleagues argue that female song is often quieter and duller and therefore "easy for researchers to miss," which directly supports the idea that apparent geographic differences could result from differences in detectability of female versus male song rather than true absence.
**Choice A is incorrect.** Neither text mentions differences in timing of mating seasons as an explanation; Rose et al. focus on detectability and frequency, not timing.
**Choice B is incorrect.** Rose and colleagues do not claim that male tropical singing has been overstated; they emphasize that female songs are less obvious and thus overlooked.
**Choice D is incorrect.** Rose et al. contend that females sing more often than assumed because they are overlooked, not because of recent environmental changes increasing singing frequency.
**Faster approach:** Look for language about why observations might be wrong (e.g., "easy to miss")—that signals a detectability explanation and points to the correct choice.'),
  ('aa58aa47-da55-5fc6-87c9-e24b8357f9a6', 3, null, '**Choice D is correct.** To determine where the tribal economic activity, which totals \$7,312,400,000, ranks compared to other industries, we can analyze the data in the table. The contributions by the other industries are as follows:
**Construction:** \$6,797,300,000
**Transportation/Warehousing:** \$12,414,600,000
**Wholesale Trade:** \$10,723,400,000
From the figures provided, we can see that:
Tribal Economic Activity (\$7,312,400,000) is greater than Construction (\$6,797,300,000). Tribal Economic Activity is less than Transportation/Warehousing (\$12,414,600,000) and Wholesale Trade (\$10,723,400,000).
This supports the conclusion made in choice D: tribal economic activity ranks above Construction but below both Transportation/Warehousing and Wholesale Trade.
**Why the other options are incorrect:**
**Choice A:** Claims that tribal economic activity is nearly equal to Transportation/Warehousing and Wholesale Trade, which is incorrect as both of those contributions are significantly higher, by over \$5 billion.
**Choice B:** States that tribal economic activity is below Transportation/Warehousing but above both Construction and Wholesale Trade, which is also incorrect, as it is not above Wholesale Trade. **Choice C:** Incorrectly lists all three industries as being less than tribal economic activity, which contradicts the numerical values in the table.'),
  ('11870692-31b3-5c04-9f81-8bb0cb97278a', 0, null, '**Choice A is correct.** The table shows that images labeled with dark irises (images 6 and 3) received higher friendliness ratings (4.03 and 3.88) and higher “would keep/would interact” scores (1.85/1.65 and 2.35/2.65) than images labeled with light irises (images 24 and 14: friendliness 2.67 and 2.11; lower keep/interact scores). Because dark irises make the pupil blend with the iris and appear larger, the data support the claim that human responses to apparent pupil size extend to dogs: images likely to make pupils look larger received more positive ratings.
**Choice B is incorrect.** It asserts the opposite direction (that dark irises produced more negative responses), but the table shows higher—more positive—ratings for dark-iris images.
**Choice C is incorrect.** The passage and table do not compare responses to dogs versus people or show that smaller pupils elicited stronger responses; the data show more positive responses for images whose irises likely made pupils appear larger.
**Choice D is incorrect.** This reverses the observed pattern: participants rated dark-iris images more favorably, not light-iris images.
**Faster approach:** Compare the average friendliness (and keep/interact) scores for dark versus light iris rows; the higher averages for dark irises directly identify the correct statement (choice A).'),
  ('b05336e4-994f-5887-9c50-5b2227a909bd', 1, null, '**Choice B is correct.** The study manipulated boxes to exclude birds; if wasps nested much more often in those bird-excluded boxes, that indicates direct competition for the same nesting sites. The additional fact that 80% of initial co-occupations in unmanipulated boxes resulted in wasp abandonment but not bird abandonment provides clear evidence that when both species encounter the same box, birds tend to displace or outcompete wasps — exactly the study’s two conclusions (competition for sites and competitive advantage for birds).
**Choice A is incorrect.** Finding that wasps often occupied boxes before birds shows temporal order but does not by itself demonstrate that birds outcompete wasps or that exclusion of birds affects wasp use.
**Choice C is incorrect.** Higher vacancy in bird-excluded boxes would not support birds having a competitive advantage; it would suggest those boxes were less used overall and does not link abandonment or displacement to bird presence.
**Choice D is incorrect.** If nesting times seldom overlapped and persistence rates were similar, that would argue against competition and against a bird advantage, contradicting the passage.
**Faster approach:** Look for an answer that shows (1) boxes without birds are used more by wasps (showing competition) and (2) when both occur, wasps leave while birds remain (showing bird advantage); pick the choice that states both facts.'),
  ('0e01e10b-bd8c-51ac-85ba-a1483a13b6ca', 3, null, '**Choice D is correct.** The partition hypothesis asserts that Eospermatopteris belonged to tropical deltaic forests while Archaeopteris belonged to arid floodplain forests, implying the two kinds of plants occupied different biomes. Finding an arid floodplain site that contains fossils of both Eospermatopteris and Archaeopteris directly contradicts that strict separation by showing the two kinds of plants coexisted in the same biome during the Devonian.
**Choice A is incorrect.** A post‑Devonian transition to a different biome does not undermine the claim about distinct Devonian biomes; it concerns a later time and so is irrelevant to the hypothesis about Devonian distributions.
**Choice B is incorrect.** The presence of additional plant species does not address whether Eospermatopteris and Archaeopteris were confined to separate biomes, so it does not directly contradict the partition hypothesis.
**Choice C is incorrect.** Finding Eospermatopteris in a tropical deltaic forest is consistent with the partition hypothesis rather than contradictory, because that is exactly where the hypothesis predicts
Eospermatopteris would be found.
**Faster approach:** Look for evidence that directly violates the hypothesis’s key claim (here, that the two plant types occupied separate biomes): the strongest support is a single site showing both plant types in the same biome.'),
  ('3bcfdc11-068a-5d25-96a0-689c7bad7b33', 3, null, '**Choice D is correct.** The teams judged specificity from two ratings: level of detail and level of traceability. If Feehan and Kandlikar actually had a lower detail rating than Oguchi and colleagues, that directly contradicts the conclusion that Feehan and Kandlikar provided more specificity, because detail is one of the explicit measures used to determine specificity.
**Choice A is incorrect.** If Oguchi had low detail and low traceability, that would support (not challenge) the conclusion that Feehan and Kandlikar provided more specificity.
**Choice B is incorrect.** A lower traceability rating for Feehan and Kandlikar weakens their case but does not necessarily overturn the conclusion—Feehan could still have higher detail that yields greater overall specificity.
**Choice C is incorrect.** If Feehan and Kandlikar had high detail and high traceability, that supports the second team’s conclusion rather than challenges it.
**Faster approach:** Identify which measured attribute(s) the conclusion depends on (detail and traceability) and pick the choice that directly contradicts those measured attributes—here, a lower detail rating for Feehan directly undermines the conclusion.'),
  ('5e6022b3-b794-5800-8915-423f53b0a808', 1, null, '**Choice B is correct.** The passage says economists usually blame country-specific characteristics (like import-export ratios) for variation in oil-shock effects, but Oladosu et al. find estimates are highly heterogeneous even within the same country and time frame. That within-country, same-time variability implies that differences in estimates arise from how studies are done (methodological discrepancies) rather than from differences between countries, so methodological issues likely contributed to the failure to produce a generalized model.
**Choice A is incorrect.** The passage already cites import-export ratios as a typical explanation; the new finding (large within-country heterogeneity) undermines, rather than supports, the idea that between-country differences explain most variation.
**Choice C is incorrect.** The passage discusses variation in economists'' estimates, not about whether conventional measures of economic activity lack sensitivity; it points to study heterogeneity rather than measurement insensitivity.
**Choice D is incorrect.** Although plausible, D is weaker than B: the passage points more directly to methodological differences as the source of heterogeneity within a single country/time, so the best inference is that methodological discrepancies contributed to the problem.
**Faster approach:** Note the contrast phrase (“recently, however”) and the key fact (heterogeneity within same country/time); eliminate choices that rely on between-country explanations and choose the option pointing to methodological differences.'),
  ('2a060526-faac-501e-98eb-b8abe591054e', 1, null, '**Choice B is correct.** Tarabien’s finding says that among consumers who value environmental conservation, a higher perception of a product’s environmental risk lowers their likelihood of buying it. The second study reports that college students had the lowest perception of the furniture’s environmental risk. If Tarabien’s relationship applies, a lower perceived risk would lead those conservation‑minded consumers to be relatively more willing to purchase the item, so college students might be more likely than other groups to buy it.
**Choice A is incorrect.** The passage gives no basis for concluding the furniture is less appealing to college students; the information concerns perceived environmental risk, not overall appeal.
**Choice C is incorrect.** A low perception of environmental risk does not imply that students prioritize other factors; it only indicates they see fewer environmental harms.
**Choice D is incorrect.** The studies described point to a potential difference in purchase likelihood tied to different perceived risk levels, so claiming no meaningful difference contradicts the given information.
**Faster approach:** Identify the conditional relationship (higher perceived environmental risk → lower purchase likelihood) and then substitute the known group characteristic (students have lower perceived risk) to infer the comparative effect on likelihood of purchase.'),
  ('5295e6b2-5798-5c85-8197-a357a7f7d605', 2, null, '**Choice C is correct.** The passage contrasts an ownership model, which imposes a per‑song cost that discourages broad acquisition, with streaming services, which charge a flat fee giving access to a large catalog so additional variety is essentially free. That reasoning predicts that listeners using streaming services will sample and consume a wider variety of music than listeners who must pay per song.
**Choice A is incorrect.** The passage does not discuss gift behavior or imply that streaming users would buy physical copies for others more than for themselves.
**Choice B is incorrect.** Nothing in the passage links purchase of compact discs to preferring older music; the argument concerns cost structure and variety, not age of music.
**Choice D is incorrect.** The passage implies streaming changes incentives and consumption; it gives no basis for concluding publishers would see no revenue change if they stopped releasing physical media.
**Faster approach:** Identify the logical prediction the authors draw from the contrast of "per‑song cost" versus "flat fee" — convert that contrast into an expected effect on variety, then match to the answer that states that effect.'),
  ('5e911747-788a-5417-a27f-6e0246e5e671', 3, null, '**Choice D is correct.** The clause introduced by "that" requires a finite verb agreeing with the singular subject "the Continental Army’s difficulty." "Is largely occurring" supplies a singular, present progressive verb phrase that correctly completes the clause: "that the Continental Army’s difficulty ... is largely occurring due to concerns..."
**Choice A is incorrect.** "Largely occurring" is a present participle phrase, not a finite verb, so it cannot serve as the main verb of the clause introduced by "that."
**Choice B is incorrect.** "Largely occur" uses the plural base-form verb "occur," which does not agree with the singular subject "difficulty."
**Choice C is incorrect.** "Have largely occurred" is plural and present-perfect in form and therefore does not agree with the singular subject; additionally, the tense conflicts with the ongoing sense expressed by the rest of the sentence.
**Faster approach:** Identify the subject ("difficulty" = singular) and choose a finite verb form that agrees with it; eliminate nonfinite participles and any plural verb forms immediately.'),
  ('3188d878-b3a8-5418-ad92-4daa2649c2f8', 1, null, '**Choice B is correct.** The sentence requires a colon after the word that introduces the explanatory clause and a comma before the conjunction "though" that begins the subordinate clause. "Concern:" correctly introduces the explanation that follows — "terms of service stipulate..." — and the comma after "though" is not needed because "though" here begins a concessive clause that follows the explanation; the correct punctuation is a colon after "concern" and a comma after "though" would be wrong, so the form "concern: though" sets up the explanation while keeping "though" as a transitional adverb. This matches the grammatical convention of using a colon to introduce an explanation or elaboration of what precedes it.
**Choice A is incorrect.** A comma before "though" plus a semicolon-like break is inappropriate here; a comma alone does not properly introduce the explanatory clause that follows.
**Choice C is incorrect.** A comma after "concern" does not provide the clear, formal introduction required for the explanatory clause "terms of service stipulate..." — a colon is needed to signal that elaboration.
**Choice D is incorrect.** A colon after "though" is incorrect because the colon must follow "concern" to introduce the explanation; placing it after "though" mispunctuates the subordinate element and leaves the explanatory lead-in unintroduced.
**Faster approach:** When a sentence needs to introduce an explanation or elaboration, scan for a colon opportunity: replace the blank with the noun and read whether the clause that follows explains that noun; if it does, choose the option with a colon after the lead-in word.'),
  ('24443e80-7628-5ed5-a8cc-9a4b798acb56', 1, null, '**Choice B is correct.** The grammatical subject of the sentence is the singular noun phrase "MindMaze’s technology." The phrase "alongside other such neuromodulation technologies that function by stimulating nervous system structures" is parenthetical and does not change the number of the subject, so the verb must be singular: "is paving." The present progressive fits the ongoing sense of enabling future advancements.
**Choice A is incorrect.** "Are paving" uses a plural verb and would require a plural subject; it does not agree with the singular "MindMaze’s technology."
**Choice C is incorrect.** "Have paved" is plural and past perfect in meaning; it disagrees in number and tense with the sentence’s intended present, ongoing sense.
**Choice D is incorrect.** "Paving" is a dangling participle here and does not form a complete verb phrase, so it fails to complete the sentence grammatically.
**Faster approach:** Identify the main subject (ignore interrupting phrases like "alongside ...") and choose a verb that agrees in number and tense with that subject.'),
  ('af85e56d-5c99-52f5-aaaa-ff8363a95187', 3, null, '**Choice D is correct.** The sentence needs a noun phrase as the subject followed by a nonrestrictive modifier set off by commas and then the main verb. "Helical swimming, widely understood to confer stability and efficiency in the locomotion of a variety of microscopic organisms—including bacteria, eukaryotic algae, and ciliates—, bestows similar advantages..." functions correctly when rendered as "Helical swimming, widely understood to confer..., bestows..." (the comma after "swimming" marks the nonrestrictive phrase).
**Choice A is incorrect.** "swimming is" produces two consecutive main verbs without proper punctuation or conjunction: "...is widely understood... bestows" is ungrammatical.
**Choice B is incorrect.** "swimming has been" creates an awkward and incorrect tense sequence and still leaves the sentence with two main verbs improperly joined.
**Choice C is incorrect.** "swimming, is" inserts an unnecessary comma before the verb, creating a comma splice and breaking subject–verb structure.
**Faster approach:** Identify whether the inserted material should be a subject noun phrase or a verb phrase and check if the following clause is a nonrestrictive modifier; use comma placement to decide between a plain subject (no comma) and a subject followed by a nonrestrictive phrase (comma before the modifier and after it).'),
  ('be8bd220-5b3b-5672-9416-24ca870d2a8d', 3, null, '**Choice D is correct.** The sentence up to the blank is a single independent clause describing Alberto Gabriele tracking dissemination; what follows is a separate independent clause that explains the magazine’s role. A period after "Belgravia" and a capitalized "Published" correctly separates the two independent clauses into two sentences: "...via the magazine Belgravia. Published from 1866 to 1899 and distributed throughout..., this magazine helped make..." The second sentence then uses the participial phrase "Published from 1866 to 1899 and distributed..." to modify "this magazine," which is placed next to it, maintaining clear syntax and standard punctuation.
**Choice A is incorrect.** A comma before "published" creates a comma splice because "published from 1866 to 1899 and distributed..." begins a participial phrase that needs to attach to the noun it modifies; the comma + lowercase verb makes the structure awkward and ungrammatical here.
**Choice B is incorrect.** Leaving no punctuation between "Belgravia" and "published" turns "Belgravia published from 1866..." into a misparsed noun phrase implying Belgravia is performing the action "published," which is not the intended participial modifier and results in incorrect syntax.
**Choice C is incorrect.** A semicolon links two independent clauses; here the clause after the semicolon begins with "published," a past participle phrase, not an independent clause, so a semicolon is inappropriate and creates a sentence-fragment problem.
**Faster approach:** Determine whether the words after the blank form an independent clause or a modifier. If they begin with a past participle phrase that modifies the magazine, use a period before it to start a new sentence (option D). If they form a full independent clause, a semicolon or comma might work. This single test quickly eliminates incorrect punctuation choices.'),
  ('5eddf112-8502-5efc-94b3-3bfe44afab47', 1, null, '**Choice B is correct.** The sentence requires a full stop after the date so that the time clause "Roughly six weeks earlier, Page’s only model had been suspiciously destroyed..." can stand as its own independent clause with an introductory adverbial phrase. Choice B provides that period and correct capitalization and punctuation, yielding two grammatically complete sentences that clearly convey the sequence of events.
**Choice A is incorrect.** It uses an em dash before "roughly" and then a period before "Page''s," creating an awkward and ungrammatical break; the punctuation does not produce a clear, independent introductory clause as required.
**Choice C is incorrect.** It lacks necessary punctuation between the date and the modifying time phrase, producing a run-on and leaving the sentence grammatically unclear.
**Choice D is incorrect.** Although em dashes can set off a parenthetical, enclosing "roughly six weeks earlier" with dashes here creates a confusing and less clear structure than a separate sentence; it also leaves the sentence’s flow and clause boundaries awkward.
**Faster approach:** When a time phrase begins a new independent idea, turn the date into a full sentence (period + capital letter) so the following adverbial phrase can introduce a complete clause—this quickly resolves punctuation and capitalization issues on similar items.'),
  ('7fc30669-6164-5d9b-acbf-a67478216585', 3, null, '**Choice D is correct.** The sentence that follows describes what happens after votes are counted, so a temporal/sequence transition is required; “Then,” signals that the awarding of seats is the next step once the votes have been tabulated, making the passage logically coherent.
**Choice A is incorrect.** “Conversely” indicates a contrast or opposite, but the second clause does not present an opposing idea; it continues the description of how proportional representation works.
**Choice B is incorrect.** “In other words” signals a restatement or clarification of the previous clause, but the second clause provides a subsequent action (awarding seats), not a paraphrase of casting votes.
**Choice C is incorrect.** “However” introduces a contrast, which is inappropriate here because the sentence that follows describes the next step in the same system rather than a contradictory point.
**Faster approach:** Look for temporal cues like “once” or “after” in the second clause; these require a sequence transition such as “then.”'),
  ('b7f81566-4f43-579e-b5eb-aa8ef4f7517b', 2, null, '**Choice C is correct.** The passage presents a situation that might lead readers to expect damage (the sculpture is exposed to rain, snow, heat, and humidity) and then offers a contrasting qualification: despite those conditions, it remains in good condition because of its corrosion-resistant steel. "That said," signals this contrast smoothly and logically.
**Choice A is incorrect.** "As a result," indicates cause-and-effect in the same direction as the preceding clause, which would illogically imply that exposure causes the sculpture to remain in good condition.
**Choice B is incorrect.** "On the contrary," is a stronger categorical contradiction and would be awkward here; the sentence does not flatly deny the prior clause but qualifies it, so a milder contrast is better.
**Choice D is incorrect.** "In addition," adds information rather than contrasting with the expectation created by the sculpture’s exposure, so it does not fit the intended reversal.
**Faster approach:** Look for whether the second clause contrasts with or continues the first; choose a contrast signal ("That said,"/"However,") when the second clause qualifies or reverses the expectation set by the first.'),
  ('4b9230a9-01d1-5869-8441-4e9f588f8be7', 2, null, '**Choice C is correct.** The first sentence presents a general tendency that a successful debut author may struggle to match that success; the second sentence provides an instance showing that this is not always true. Beginning the sentence with "Sometimes," signals that the following clause describes an exception or an occasional alternative — "Sometimes, as in the case of Tommy Orange... the follow-up actually elevates the writer’s reputation." This creates the intended contrast between the general tendency and an occasional counterexample.
**Choice B is incorrect.** "For example," could introduce an instance, but the passage sets up a contrast (may struggle vs. a case that doesn’t), so "Sometimes," better signals that this is an occasional exception. "For example," is weaker here.
**Choice A is incorrect.** "Specifically," implies narrowing or clarifying the preceding idea rather than presenting an occasional counterexample, so it does not fit the intended contrast.
**Choice D is incorrect.** "Accordingly," indicates a consequence of the first sentence; here the second sentence is not a consequence but an exception, so "Accordingly," is inappropriate.
**Faster approach:** Identify whether the second sentence is giving an example that confirms, contrasts with, or follows from the first; then choose the transition that signals that relationship (use "Sometimes" for an occasional exception, "Accordingly" for a consequence, "Specifically" for narrowing, and "For example" for a straightforward supporting instance).'),
  ('c2e20b2d-0cc5-5fc7-8ea5-0b905349be0c', 1, null, '**Choice B is correct.** The sentence before the blank states a cause (rendering from perfect geometric shapes) and its effect (lacking organic realism). "As such" signals a logical consequence, so it appropriately introduces a specific consequence: that these 3D elements may display unnaturally precise angles and curves compared with real-world objects.
**Choice A is incorrect.** "In conclusion" signals a final summary or wrap-up, which is inappropriate in the middle of an explanatory pair of sentences.
**Choice C is incorrect.** "However" indicates contrast; because the previous clause already sets up a cause-effect relationship, the sentence needs a consequence marker rather than a contrasting one.
**Choice D is incorrect.** "In addition" would add another similar point, but the second sentence gives a specific result of the stated cause, so a consequence connector like "As such" is stronger and more logical.
**Faster approach:** Identify whether the second sentence presents a consequence, contrast, or addition; choose a transition word that matches that relationship (e.g., "As such" for consequence, "However" for contrast).'),
  ('a25b3e7e-ee57-55d3-8648-cadcc441dd6f', 0, null, '**Choice A is correct.** It directly contrasts the two specimens by naming each specimen and giving the specific museum and city/country where each is housed, which uses the relevant location information from the notes to accomplish the student’s goal.
**Choice B is incorrect.** It compares the specimens’ time period (Late Cretaceous) rather than contrasting their locations, so it does not address the prompt.
**Choice C is incorrect.** It makes a general claim about other specimens being housed in museums, which does not contrast the locations of Raymond and Dio and introduces information not in the notes.
**Choice D is incorrect.** It names only Dio’s location and so fails to contrast the two specimens’ locations as requested.
**Faster approach:** Look for the answer that names both specimens and lists both locations; eliminate choices that mention only one specimen or that compare something other than location.'),
  ('b39dfbf8-20cf-5587-8dce-4c9748ded96d', 2, null, '**Choice C is correct.** The notes state that synthetic languages have extensive case systems and that nouns can take different forms depending on their function; the example given is that adding the suffix -de to boo yields boode (“in the house”), which directly shows Manchu’s case marking. Choice C succinctly and accurately uses that information to explain why Manchu is classified as synthetic.
**Choice A is incorrect.** It is vague and misleading: saying the Tungusic language "utilizes nouns to fulfill various functions" does not identify the key feature (case marking) that makes a language synthetic.
**Choice B is incorrect.** Although it correctly contrasts synthetic and analytic languages, it fails to state the specific evidence that Manchu is synthetic (the presence of case forms and the suffix example).
**Choice D is incorrect.** It states the opposite of the notes by claiming Manchu indicates function mainly through word order and auxiliary words and misrepresents -de as a separate word rather than a suffix.
**Faster approach:** For rhetorical-synthesis questions, look for an answer that repeats the passage’s explicit definition or example (here, "case system" and the boo→boode example) and eliminate choices that are vague, reversed, or that misstate details.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;

