insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('464f44f0-3096-58da-9909-f13959ddb1bf', '836233eb-bab6-5cab-807d-e1970a86a776', 'For the linear function $f$, $f(0) = 0$ and $f(40) = 8$. Which equation defines $f$?', '["$f(x) = \\frac{x}{8}$", "$f(x) = \\frac{x}{5}$", "$f(x) = x + 5$", "$f(x) = x + 8$"]'::jsonb, 1, null),
  ('3fbf1c49-3be3-57a4-a566-dcdf0cd52050', '836233eb-bab6-5cab-807d-e1970a86a776', 'The exponential function $g$ is defined by $g(x) = 18 \cdot a^{x}$, where $a$ is a positive constant. If $g(3) = 486$, what is the value of $g(4)$?', '[]'::jsonb, 2, null),
  ('065aa704-540e-5b2f-a92f-c428df30744a', '836233eb-bab6-5cab-807d-e1970a86a776', 'In the figure, line $n$ is parallel to line $s$, and both lines are intersected by line $t$. If $x = 6z - 87$ and $y =$ $3z + 51$, what is the value of $z$?', '["$14$", "$24$", "$46$", "$57$"]'::jsonb, 3, '![figure](/q/oct25/003.webp)'),
  ('a9ec7fde-34dd-5845-8a57-5c6a39a2ae7c', '836233eb-bab6-5cab-807d-e1970a86a776', 'The point $(x,38)$ is a solution to the given system of inequalities in the $xy$-plane. Which of the following could be the value of $x$?
$y > 15$
$3x + y < 19$', '["$7$", "$3$", "$-3$", "$-7$"]'::jsonb, 4, null),
  ('f7945b68-3005-5d67-8bf9-d0f6935a7f15', '836233eb-bab6-5cab-807d-e1970a86a776', 'The function $f(x) = 231(1.026)^{x}$ models the value, in dollars, of a certain bank account from 1953 through 1973, where $x$ is the number of years after the end of 1953. Which of the following is the best interpretation of “$f(5)$ is approximately equal to 263” in this context?', '["The value of the bank account is estimated to be approximately 5 dollars greater at the end of 1958 than at the end of 1953.", "The value of the bank account is estimated to be approximately 263 dollars at the end of 1958.", "The value, in dollars, of the bank account is estimated to be approximately 5 times greater at the end of 1958 than at the end of 1953.", "The value of the bank account is estimated to increase by approximately 263 dollars every 5 years between the end of 1953 and the end of 1973."]'::jsonb, 5, null),
  ('1020c09b-841a-5b08-b77c-f54c0c3ce434', '836233eb-bab6-5cab-807d-e1970a86a776', 'For all values of $x$, the given expression is equivalent to which of the following?
$(5x + 10)(2x + 1) - (2x - 18)$
I. $10x^{2} + 23x + 28$
II. $10x^{2} + 25x + 10 - 2x - 18$', '["I only", "II only", "I and II", "Neither I nor II"]'::jsonb, 6, null),
  ('b8c291d4-a057-5ad9-9a93-951346f83a33', '836233eb-bab6-5cab-807d-e1970a86a776', '$y < 4x + 15$
For which of the following tables are all the values of $x$ and their corresponding values of $y$ solutions to the given inequality?', '["| x | y |\n| 2 | 22 |\n| 4 | 29 |\n| 6 | 35 |", "| x | y |\n| 2 | 23 |\n| 4 | 31 |\n| 6 | 39 |", "| x | y |\n| 2 | 24 |\n| 4 | 33 |\n| 6 | 42 |", "| x | y |\n| 2 | 20 |\n| 4 | 32 |\n| 6 | 38 |"]'::jsonb, 7, null),
  ('fa8aa09a-6e7c-5943-8f08-1cd74ff12215', '836233eb-bab6-5cab-807d-e1970a86a776', 'The function $f$ is defined by $f(x) = -\frac{1}{4}(x - 9) + 4$. For what value of $x$ does $f(x) = 2a$, where $a$ is a constant?', '["$-8a + 25$", "$-8a - 7$", "$-\\frac{a}{2} + \\frac{25}{4}$", "$-\\frac{a}{2} + \\frac{7}{4}$"]'::jsonb, 8, null),
  ('441efd03-1713-5dee-a939-44ab77701960', '836233eb-bab6-5cab-807d-e1970a86a776', 'If $\sqrt{(x - 5)} = 8$, what is the value of $(x - 5)$?', '["$8$", "$59$", "$64$", "$128$"]'::jsonb, 9, null),
  ('4bc7a15b-8031-5c6c-af80-8fecff70588d', '836233eb-bab6-5cab-807d-e1970a86a776', 'The solution to the given system of equations is $(x,y)$. What is the value of $8x + 6y$?
$2(8x) + 7(6y) = 21$
$-2(8x) + 7(6y) = 21$', '["$0.5$", "$1.5$", "$3$", "$21$"]'::jsonb, 10, null),
  ('13a6c91a-d644-56b4-ba0c-924adffb6c19', '836233eb-bab6-5cab-807d-e1970a86a776', 'The given expression, where $b$ is a constant, is equivalent to $(3x^{9} + q)(rx^{9} + 2)$, where $q$ and $r$ are constants. What is the value of $b$?
$57x^{18} + bx^{9} + 34$', '["4", "8", "329", "114"]'::jsonb, 11, null),
  ('66828ea1-d3db-598e-8fa6-6363aa423547', '836233eb-bab6-5cab-807d-e1970a86a776', 'I. The median number of points per game for the new data set is less than the median number of points per game for the original data set.
II. The mean number of points per game for the new data set is less than the mean number of points per game for the original data set.', '["I only", "II only", "I and II", "Neither I nor II"]'::jsonb, 12, '![figure](/q/oct25/004.webp)

The histogram summarizes the distribution of an original data set that represents the number of points per game a basketball team has scored in the last $50$ games played. If the team scores $17$ points in the next game and this game is added to the original data set to create a new data set of $51$ values, which of the following must be true?'),
  ('7f14907b-d062-5951-8236-d9eaf2a53de1', '836233eb-bab6-5cab-807d-e1970a86a776', '$g(x) = x^{3} + ax^{2} + bx + c$
The function $g$ is defined by the given equation, where $a$, $b$, and $c$ are integer constants. The zeros of the function are $-2$, $-7$, and $3$. What is the value of $a$?', '["$-42$", "$-6$", "$6$", "$42$"]'::jsonb, 13, null),
  ('41b972a2-fd1b-51ca-9b8e-ffc355d592b9', '836233eb-bab6-5cab-807d-e1970a86a776', '$f(x) = 18(2.10)^{\frac{x}{2}}$ The function $f$ is defined by the given equation. The value of $f(x)$ increases by $p%$ for every increase of $x$ by 4. For which of the following functions, where $n$ is a positive constant, does the value of $g(x)$ increase by $p%$ for every increase of $x$ by 1?', '["$g(x) = n(1.05)^{x}$", "$g(x) = n(2.10)^{x}$", "$g(x) = n(3.41)^{x}$", "$g(x) = n(4.41)^{x}$"]'::jsonb, 14, null),
  ('ded9d3c5-08f0-527c-a768-26238d0541b4', '836233eb-bab6-5cab-807d-e1970a86a776', 'Each $3.0$-ounce serving of cheddar cheese and each $1.2$-ounce serving of tuna provides about $1$ microgram of vitamin B12. If a total of $3.1$ micrograms of vitamin B12 are consumed from eating $x$ ounces of cheese and $y$ ounces of tuna, which equation best represents this situation?', '["$0.83x + 0.33y = 3.1$", "$3.0x + 1.2y = 3.1$", "$1.2x + 3.0y = 3.1$", "$0.33x + 0.83y = 3.1$"]'::jsonb, 15, null),
  ('03b8b4ed-8a00-5fae-9e19-11d445a7c646', '836233eb-bab6-5cab-807d-e1970a86a776', 'A circle in the xy-plane has its center at $(-4,4)$ and has a radius of $6$. An equation of this circle is $x^{2} +$ $y^{2} + ax + by + c = 0$, where $a$, $b$, and $c$ are constants. What is the value of $c$?', '[]'::jsonb, 16, null),
  ('b938d9ef-7ec4-5a22-8766-d4ff8041aeb6', '836233eb-bab6-5cab-807d-e1970a86a776', 'The right rectangular prism X is similar to the right rectangular prism Y. The surface area of right rectangular prism X is $62$ square centimeters ($\text{cm}^{2}$), and the surface area of right rectangular prism Y is $1,550\text{cm}^{2}$. The volume of the right rectangular prism X is $16.8$ cubic centimeters ($\text{cm}^{3}$). What is the volume, in $\text{cm}^{3}$, of the right rectangular prism Y?', '[]'::jsonb, 17, null),
  ('6663deef-e55f-5bb3-bbb1-07f4aa004020', '836233eb-bab6-5cab-807d-e1970a86a776', 'A researcher investigated two species of mites: a predator and its prey. At the start of a week, there was an equal number of the two species. At the end of the week, the number of prey had increased by $2100%$ of the number of prey at the start of the week, and the number of predators had increased by $450%$ of the number of predators at the start of the week. The number of predators at the end of the week was $p%$ less than the number of prey at the end of the week. What is the value of $p$?', '[]'::jsonb, 18, null),
  ('9b63fe8b-2999-5c9a-9617-9d3d4e34c4c3', '836233eb-bab6-5cab-807d-e1970a86a776', 'The area of a rectangular region is increasing at a rate of $220$ square feet per hour. Which of the following is closest to this rate in square meters per minute? (Use $1$ meter $=3.28$ feet.)', '["$0.34$", "$1.12$", "$12.03$", "$20.45$"]'::jsonb, 19, null),
  ('daed92e8-a9e2-540f-94e4-54a77eebe25e', '836233eb-bab6-5cab-807d-e1970a86a776', 'Line $k$ is shown in the $xy$-plane. Line $n$ (not shown) is perpendicular to line $k$ and passes through the point $(2,7)$. Which equation defines line $n$?', '["$y = -(3/2)x + 4$", "$y = -(3/2)x + 10$", "$y = (2/3)x + 4$", "$y = (2/3)x + 10$"]'::jsonb, 20, '![figure](/q/oct25/005.webp)'),
  ('4406aec6-df1a-5451-92ab-1d44d1f3f72c', '836233eb-bab6-5cab-807d-e1970a86a776', 'The scatterplot shows the relationship between two variables, $x$ and $y$. A line of best fit for the data is also shown. For how many of the $9$ data points is the actual $y$-value greater than the $y$-value predicted by the line of the best fit.', '["$2$", "$5$", "$7$", "$8$"]'::jsonb, 21, '![figure](/q/oct25/006.webp)'),
  ('2b641475-97c3-5f64-9349-dde09fbe5ba5', '836233eb-bab6-5cab-807d-e1970a86a776', 'If $9(8 - 3x) + 2 = 8(8 - 3x) + 19$, what is the value of $8 - 3x$?', '["$-17$", "$-3$", "$17$", "$3$"]'::jsonb, 22, null)
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('464f44f0-3096-58da-9909-f13959ddb1bf', 1, null, '**Choice B is correct.** Because $f$ is linear and $f(0) = 0$, the equation has the form $f(x) = mx$. Using $f(40) = 8$ gives $m = 8/40 = 1/5$, so $f(x) = \frac{x}{5}$.
**Choice A is incorrect.** $f(x) = \frac{x}{8}$ would give $f(40) = 40/8 = 5$, not 8, so the slope is too small. **Choice C is incorrect.** $f(x) = x + 5$ does not satisfy $f(0) = 0$ (it gives $f(0) = 5$), so it cannot be the correct line through the origin.
**Choice D is incorrect.** $f(x) = x + 8$ also fails $f(0) = 0$ (it gives $f(0) = 8$) and would give $f(40) = 48$, not 8.
**Faster approach:** Use the origin to note $f(x) = mx$, then compute the slope directly as $m = \frac{8-0}{40-0} = \frac{1}{5}$ and write $f(x) = \frac{x}{5}$.'),
  ('3fbf1c49-3be3-57a4-a566-dcdf0cd52050', null, array['1458']::text[], '**The correct answer is 1458.** Since $g(x) = 18 \cdot a^{x}$ and $g(3) = 486$, substitute $x = 3$ to get $18 \cdot a^{3} = 486$. Solving gives $a^{3} = 486/18 = 27$, so $a = 3$. Then $g(4) = 18 \cdot a^{4} = 18 \cdot 3^{4} = 18 \cdot 81 = 1458$.
**Faster approach:** Note that $g(4) = 18 \cdot a^{4} = (18 \cdot a^{3}) \cdot a = g(3) \cdot a$. From $18 \cdot a^{3} = 486$ we get $a = 3$, so $g(4) = 486 \cdot 3 = 1458$ — compute one division and one multiplication.'),
  ('065aa704-540e-5b2f-a92f-c428df30744a', 1, null, '**Choice B is correct.** The two marked angles lie on the same side of the transversal and are interior/exterior in positions that make them a linear pair across the two parallel lines, so they are supplementary. Therefore $x +$ $y = 180$. Substitute the expressions: $(6z - 87) + (3z + 51) = 180$, so $9z - 36 = 180$, $9z = 216$, and $z = 24$.
**Choice A is incorrect.** If $z = 14$, the equations would not satisfy the correct supplementary relation; plugging $z = 14$ gives $x = 6(14) - 87 = -3$ and $y = 3(14) + 51 = 93$, which do not add to $180$.
**Choice C is incorrect.** That value comes from assuming $x = y$ (which would give $z = 46$), but the diagram indicates the two marked angles are not corresponding congruent angles, so they are not equal.
**Choice D is incorrect.** Substituting $z = 57$ gives values that do not satisfy the relationship $x + y = 180$, so this choice is not valid.
**Faster approach:** Identify whether the two marked angles are congruent (set equal) or supplementary (sum to $180$) by their relative positions with respect to the parallel lines and the transversal; then solve the resulting linear equation for $z$.'),
  ('a9ec7fde-34dd-5845-8a57-5c6a39a2ae7c', 3, null, '**Choice D is correct.** Substituting $y = 38$ into $3x + y < 19$ gives $3x + 38 < 19$, so $3x < -19$ and $x < -\frac{19}{3} \approx$ $-6.333$. Of the choices, only $-7$ is less than $-6.333$, so $x = -7$ satisfies both $y > 15$ and $3x + y < 19$.
**Choice A is incorrect.** For $x = 7$, $3x + 38 = 21 + 38 = 59$, and $59 < 19$ is false, so $(7,38)$ does not satisfy the second inequality.
**Choice B is incorrect.** For $x = 3$, $3x + 38 = 9 + 38 = 47$, and $47 < 19$ is false, so $(3,38)$ is not a solution.
**Choice C is incorrect.** For $x = -3$, $3x + 38 = -9 + 38 = 29$, and $29 < 19$ is false, so $(-3,38)$ does not satisfy the system.
**Faster approach:** Plug $y = 38$ into $3x + y < 19$ to get $3x < -19$, so $x < -19/3$. Quickly scan choices for the one less than $-19/3$ (only $-7$).'),
  ('f7945b68-3005-5d67-8bf9-d0f6935a7f15', 1, null, '**Choice B is correct.** The function gives the account value in dollars when $x$ is years after the end of 1953, so $f(5)$ is the account value 5 years later (the end of 1958). Evaluating $f(5) = 231(1.026)^{5} \approx 231(1.137) \approx 263$, so the account is estimated to be about $263$ at the end of 1958.
**Choice A is incorrect.** It claims the account is about $5$ dollars greater than at the end of 1953, but $f(0) = 231$, and $f(5) \approx 263$, which is about $32$ dollars greater, not $5$.
**Choice C is incorrect.** It asserts the value is about 5 times greater; $f(5) \approx 263$ is only about $1.14$ times $231$, not 5 times.
**Choice D is incorrect.** It says the account increases by about $263$ every 5 years; $263$ is the account value at 5 years, not the amount of increase (the increase is about $263 - 231 \approx 32$).
**Faster approach:** Identify what the input $x$ represents (years after 1953). Then interpret $f(5)$ directly as the modeled dollar value 5 years later—no algebra beyond that is needed.'),
  ('1020c09b-841a-5b08-b77c-f54c0c3ce434', 0, null, '**Choice A is correct.** Expanding $(5x + 10)(2x + 1)$ gives $10x^{2} + 25x + 10$. Subtracting $(2x - 18)$ means subtract $2x$ and add $18$, so the result is $10x^{2} + (25x - 2x) + (10 + 18) = 10x^{2} + 23x + 28$, which matches statement I.
**Choice B is incorrect.** Statement II is $10x^{2} + 25x + 10 - 2x - 18$, which simplifies to $10x^{2} + 23x - 8$, not $10x^{2} + 23x + 28$, so II is not equivalent to the given expression.
**Choice C is incorrect.** It asserts both I and II are equivalent; II is not, so this choice is false.
**Choice D is incorrect.** It asserts neither I nor II is equivalent; I is equivalent, so D is false.
**Faster approach:** FOIL $(5x + 10)(2x + 1)$ to get $10x^{2} + 25x + 10$, then distribute the leading minus across $(2x - 18)$ (giving $-2x + 18$) and combine like terms; this expansion-and-combine method always works for verifying equivalent polynomial expressions.'),
  ('b8c291d4-a057-5ad9-9a93-951346f83a33', 0, null, '**Choice A is correct.** For each x compute $4x + 15$: when $x = 2$, $4x + 15 = 23$ and $y = 22 < 23$; when $x = 4$, $4x + 15 = 31$ and $y = 29 < 31$; when $x = 6$, $4x + 15 = 39$ and $y = 35 < 39$. All three ordered pairs satisfy $y <$ $4x + 15$, so every entry in table A is a solution.
**Choice B is incorrect.** For $x = 2$ we have $4x + 15 = 23$, but the table gives $y = 23$, and $23$ is not less than $23$, so that pair does not satisfy the inequality.
**Choice C is incorrect.** For $x = 2$, $4x + 15 = 23$ but the table gives $y = 24 > 23$, so that pair fails the inequality.
**Choice D is incorrect.** For $x = 4$, $4x + 15 = 31$ but the table gives $y = 32 > 31$, so that entry does not satisfy the inequality.
**Faster approach:** Compute $4x + 15$ for each given $x$ once (here 23, 31, 39) and check that each listed $y$ is strictly less than the corresponding number; reject any table with a $y$ equal to or greater than that value.'),
  ('fa8aa09a-6e7c-5943-8f08-1cd74ff12215', 0, null, '**Choice A is correct.** Start with $f(x) = -\frac{1}{4}(x - 9) + 4$ and set it equal to $2a$: $-\frac{1}{4}(x - 9) + 4 = 2a$. Distribute and combine like terms: $-\frac{1}{4}x + \frac{9}{4} + 4 = 2a$, and $\frac{9}{4} + 4 = \frac{25}{4}$, so $-\frac{1}{4}x + \frac{25}{4} = 2a$. Subtract $\frac{25}{4}$: $-\frac{1}{4}x = 2a - \frac{25}{4}$. Multiply both sides by $-4$ to solve for $x$: $x = -8a + 25$, which matches choice A.
**Choice B is incorrect.** It differs by a constant term: $-8a - 7$ would result if arithmetic combining the constant terms were done incorrectly; the correct constant is $+25$, not $-7$.
**Choice C is incorrect.** Rewriting $x = -8a + 25$ as a form involving $-\frac{a}{2}$ would require dividing by 16; $-\frac{a}{2} + \frac{25}{4}$ is not algebraically equivalent to $-8a + 25$.
**Choice D is incorrect.** Like C, this has the wrong coefficient on $a$ and the wrong constant; it does not satisfy the equation when substituted back into the function.
**Faster approach:** Isolate the linear term quickly: move the constant $4$ and the $9/4$ term to the other side then multiply by $-4$ to get $x$ directly. This avoids extra fraction manipulation and works for any linear equation of the form $m(x - b) + c = d$.'),
  ('441efd03-1713-5dee-a939-44ab77701960', 2, null, '**Choice C is correct.** Because the equation is $\sqrt{x - 5} = 8$, square both sides to undo the square root: $x -$ $5 = 8^{2} = 64$. Thus $(x - 5) = 64$, which matches Choice C.
**Choice A is incorrect.** It confuses the square root result with the radicand; $\sqrt{x - 5} = 8$ does not mean $x -$ $5 = 8$ but rather $x - 5 = 8^{2}$.
**Choice B is incorrect.** There is no algebraic step that yields 59 from $\sqrt{x - 5} = 8$; squaring 8 gives 64, not 59.
**Choice D is incorrect.** 128 is $2 \times 64$ and does not come from squaring 8, so it is not the value of $x - 5$.
**Faster approach:** To remove a square root, square both sides immediately: if $\sqrt{A} = B$ (with $B \ge 0$), then $A = B^{2}$. This undoes the root in one step for any similar problem.'),
  ('4bc7a15b-8031-5c6c-af80-8fecff70588d', 2, null, '**Choice C is correct.** Let $A = 8x$ and $B = 6y$. The system becomes $2A + 7B = 21$ and $-2A + 7B = 21$. Adding the two equations gives $14B = 42$, so $B = 3$. Substituting back (or subtracting the equations) gives $A = 0$. Thus $8x + 6y = A + B = 0 + 3 = 3$, so choice C is correct.
**Choice A is incorrect.** It equals $0.5$, but as shown $8x + 6y = 3$, not $0.5$.
**Choice B is incorrect.** It equals $1.5$, which does not match the sum $A + B = 3$ found by solving the system.
**Choice D is incorrect.** It equals $21$, but that is the right-hand side of each equation, not the value of $8x + 6y$.
**Faster approach:** Treat $8x$ and $6y$ as single variables, add the two equations to eliminate $8x$ (or subtract to eliminate $6y$) and solve directly for the desired sum; elimination always works for two linear equations in two unknowns.'),
  ('13a6c91a-d644-56b4-ba0c-924adffb6c19', 2, null, '**Choice C is correct.** Expand $(3x^{9} + q)(rx^{9} + 2)$ to get $3rx^{18} + (6 + qr)x^{9} + 2q$. Matching coefficients with $57x^{18} + bx^{9} + 34$ gives $3r = 57$, so $r = 19$, and $2q = 34$, so $q = 17$. Then $b = 6 + qr = 6 + 17 \cdot 19 = 6 +$ $323 = 329$, which is choice C.
**Choice A is incorrect.** If $b = 4$, the middle coefficient would not equal $6 + qr$ after solving $r$ and $q$ from the other terms; numeric substitution shows $4 \ne 329$.
**Choice B is incorrect.** $8$ is far from the required $6 + 17 \cdot 19 = 329$, so it does not match the product’s middle coefficient.
**Choice D is incorrect.** $114$ does not equal $6 + qr$ with $q = 17$ and $r = 19$, so it cannot be the correct middle coefficient.
**Faster approach:** Match coefficients: set $3r = 57$ and $2q = 34$ to find $r$ and $q$, then compute $b = 6 + qr$. This uses only three quick arithmetic steps and always works for matching coefficients in a product of binomials.'),
  ('66828ea1-d3db-598e-8fa6-6363aa423547', 1, null, '**Choice B is correct.** The histogram shows counts of 50 games distributed as 5 values in the 40–50 bin, 28 values in the 50–60 bin, 12 values in the 60–70 bin, and the remaining 5 values in the bins below 40 (these add to 50). For the original 50-game set the median is the average of the 25th and 26th values. Because there are only 5 + 5 = 10 values below 50, the 25th and 26th values both lie in the 50–60 bin, so the original median is in that bin. After adding a 17 (which lies below 50), there are 51 values and the median is the 26th value; with only 11 values below 50 after the addition, the 26th value still falls in the 50–60 bin, so the median does not have to decrease.
**Choice A is incorrect.** The median need not decrease: inserting a single low score when the middle values are in a much higher-frequency upper bin can leave the median unchanged, as here.
**Choice C is incorrect.** Although the mean will decrease, the median does not necessarily decrease, so both statements are not true.
**Choice D is incorrect.** Statement II is true: adding a value (17) that is below the original mean must decrease the mean, so it is not the case that neither statement is true.
**Faster approach:** Use cumulative counts to find where the median position falls (25th/26th for 50 items, 26th for 51). For means, remember: adding a number below the original mean always lowers the mean; adding one above always raises it.'),
  ('7f14907b-d062-5951-8236-d9eaf2a53de1', 2, null, '**Choice C is correct.** To find the value of $a$ in the polynomial function $g(x) = x^{3} + ax^{2} + bx + c$, we first need to use the fact that the zeros of the function are $-2$, $-7$, and $3$. This means we can express the polynomial in factored form as follows:
$g(x) = (x + 2)(x + 7)(x - 3)$
Next, we will expand this expression. Start by multiplying the first two factors:
$(x + 2)(x + 7) = x^{2} + 7x + 2x + 14 = x^{2} + 9x + 14$
Now, we multiply this result with the third factor $(x - 3)$:
$g(x) = (x^{2} + 9x + 14)(x - 3)$
We use the distributive property (FOIL) to expand:
$x^{2} \cdot x = x^{3}$
$x^{2} \cdot (-3) = -3x^{2}$
$9x \cdot x = 9x^{2}$
$9x \cdot (-3) = -27x$
$14 \cdot x = 14x$
$14 \cdot (-3) = -42$
Putting all these terms together results in:
$g(x) = x^{3} + (9x^{2} - 3x^{2}) + (-27x + 14x) - 42$
This simplifies to:
$g(x) = x^{3} + 6x^{2} - 13x - 42$
Now, we can identify the value of $a$ as $6$. Thus, the answer is:
$a = 6$
Now, for why the other options are incorrect:
**Option A:** $-42$ is incorrect because it does not match the calculated value of $a$ and is just the constant term $c$ in the polynomial.
**Option B:** $-6$ is incorrect because $a$ cannot be negative in this case; the expanded polynomial shows $a = 6$.
**Option D:** $42$ is incorrect because it represents the absolute value of the constant term, not the coefficient $a$ in the $x^{2}$ term.'),
  ('41b972a2-fd1b-51ca-9b8e-ffc355d592b9', 3, null, '**Choice D is correct.** For $f$ the factor by which the value increases when $x$ increases by 4 is $\frac{f(x + 4)}{f(x)} =$ $(2.10)^{(x+4)/2}/(2.10)^{x/2} = (2.10)^{4/2} = (2.10)^{2} = 4.41.$ That factor equals $1 + \frac{p}{100}$, so the percentage increase $p%$ corresponds to multiplying by $4.41$ for a $4$-unit increase. We need a function $g(x) = n \cdot b^{x}$ whose value multiplies by $4.41$ when $x$ increases by $1$, so $b = 4.41$. Thus $g(x) = n(4.41)^{x}$, Choice D.
**Choice A is incorrect.** $g(x) = n(1.05)^{x}$ multiplies by $1.05$ for a unit increase, not by $4.41$, so it does not match the given $p%$.
**Choice B is incorrect.** $g(x) = n(2.10)^{x}$ multiplies by $2.10$ for each unit increase, not $4.41$.
**Choice C is incorrect.** $g(x) = n(3.41)^{x}$ multiplies by $3.41$ per unit increase, also not $4.41$.
**Faster approach:** Compute the growth factor for the given interval: find $f(x + 4)/f(x)$. Use that factor as the base of $g(x) = n(\text{factor})^{x}$ so one-unit increases multiply by the same factor.'),
  ('ded9d3c5-08f0-527c-a768-26238d0541b4', 3, null, '**Choice D is correct.** Each 3.0-ounce serving of cheese gives 1 microgram, so each ounce of cheese gives $1/3.0 \approx 0.33$ micrograms; each 1.2-ounce serving of tuna gives 1 microgram, so each ounce of tuna gives $1/1.2 \approx 0.83$ micrograms. The total vitamin B12 from $x$ ounces of cheese and $y$ ounces of tuna is $0.33x +$ $0.83y$, which equals the given total $3.1$, so $0.33x + 0.83y = 3.1$.
**Choice A is incorrect.** It swaps the per-ounce rates: $0.83x + 0.33y = 3.1$ would imply cheese provides $0.83$ per ounce and tuna $0.33$ per ounce, the reverse of what the problem states.
**Choice B is incorrect.** $3.0x + 1.2y = 3.1$ treats the ounces per serving as micrograms per ounce rather than using the reciprocal; it would be correct only if each ounce (not each serving) provided 1 microgram.
**Choice C is incorrect.** $1.2x + 3.0y = 3.1$ also misassigns the rates and confuses ounces per serving with micrograms per ounce.
**Faster approach:** Convert “1 microgram per N ounces” to micrograms per ounce by taking the reciprocal $1/N$, then multiply by $x$ or $y$ and set the sum equal to the total. This avoids working with whole servings.'),
  ('03b8b4ed-8a00-5fae-9e19-11d445a7c646', null, array['-4']::text[], '**The correct answer is -4.** Write the circle in center–radius form: $(x + 4)^{2} + (y - 4)^{2} = 6^{2}$. Expanding gives $x^{2} + 8x + 16 + y^{2} - 8y + 16 = 36$, so $x^{2} + y^{2} + 8x - 8y + (32 - 36) = 0$, which simplifies to $x^{2} + y^{2} + 8x -$ $8y - 4 = 0$. Thus $c = -4$.
**Faster approach:** Use the expansion formula $c = h^{2} + k^{2} - r^{2}$ for a circle with center $(h,k)$ and radius $r$. Here $h = -4$, $k = 4$, $r = 6$, so $c = (-4)^{2} + 4^{2} - 6^{2} = 16 + 16 - 36 = -4$.'),
  ('b938d9ef-7ec4-5a22-8766-d4ff8041aeb6', null, array['2100']::text[], '**The correct answer is 2100.** For similar three-dimensional figures, linear dimensions scale by a factor $k$, surface areas scale by $k^{2}$, and volumes scale by $k^{3}$. Given the surface areas, $k^{2} = \frac{1550}{62} = 25$, so $k = 5$. The volume of prism Y is $k^{3}$ times the volume of prism X, so $V_{Y} = 5^{3} \times 16.8 = 125 \times 16.8 = 2100$.
**Faster approach:** Compute the surface-area ratio, take its square root to get the linear scale $k$, then multiply the given volume by $k^{3}$. This three-step procedure (ratio → sqrt → cube) works for any similar solids problem relating surface area and volume.'),
  ('6663deef-e55f-5bb3-bbb1-07f4aa004020', null, array['75']::text[], '**The correct answer is 75.** Let the starting number of each species be $N$. The prey increased by $2100%$ of $N$, so the final number of prey is $N + 21N = 22N$. The predators increased by $450%$ of $N$, so the final number of predators is $N + 4.5N = 5.5N = \frac{11}{2}N$. If the predators are $p%$ less than the prey, then $\frac{11}{2}N = 22N (1 - \frac{p}{100})$. Dividing by $N$ and by 22 gives $\frac{1}{4} = 1 - \frac{p}{100}$, so $\frac{p}{100} = \frac{3}{4}$ and $p = 75$.
**Faster approach:** Immediately set the initial amount to 1. Final prey = $1 + 21 = 22$, final predators = $1 +$ $4.5 = 5.5$. Compute $5.5/22 = 1/4$, so predators are $75%$ less than prey, giving $p = 75$. This plug-in saves algebra every time for percent-change ratio problems.'),
  ('9b63fe8b-2999-5c9a-9617-9d3d4e34c4c3', 0, null, '**Choice A is correct.** Convert $220$ ft/hr to m/min. Since $1 \text{m} = 3.28 \text{ft}$, $1 \text{ft} = (1/3.28) \text{m}$, so $1 \text{ft}^{2} =$
$22$
$2$
$(1/3.28)^{2} \text{m}^{2}$. Thus $220 \cdot (1/3.28)^{2} \approx 220 \cdot 0.09296 \approx 20.4512$ m/hr. Convert hours to minutes by dividing by
$2$
$60$: $20.4512/60 \approx 0.34085 \approx 0.34$ m/min.
**Choice B is incorrect.** $1.12$ is about three times larger than the correct value; it would result from an incorrect conversion factor (for instance, failing to square the linear conversion or dividing by a much smaller time factor).
**Choice C is incorrect.** $12.03$ is far too large; it would correspond to converting to m/hr correctly but then not dividing by $60$ (and also using a wrong area conversion).
$2$
**Choice D is incorrect.** $20.45$ equals the value in m/hr (before converting to minutes), not m/min, so it does not match the requested units.
$22$
**Faster approach:** Multiply by the area conversion $(1/3.28)^{2}$ to go ft→m, then divide by $60$ to go hours→minutes; do the arithmetic with a calculator or approximate $(1/3.28)^{2} \approx 0.093$ to get the answer quickly.
$22$'),
  ('daed92e8-a9e2-540f-94e4-54a77eebe25e', 1, null, '**Choice B is correct.** Line n is perpendicular to line k, so its slope is the negative reciprocal of the slope of k. From the graph, line k rises 2 units for every 3 units run (slope $m_{k} = 2/3$), so the slope of n is $m_{n} = -3/2$. Using point-slope with point $(2,7)$ gives $7 = (-3/2)(2) + b$, so $7 = -3 + b$ and $b = 10$. Thus the equation is $y = -\frac{3}{2}x + 10$, choice B.
**Choice A is incorrect.** It has the correct slope $-3/2$ but the y-intercept 4 does not satisfy $(2,7)$ (plugging in $x = 2$ gives $y = -3 + 4 = 1$, not 7).
**Choice C is incorrect.** Its slope $2/3$ is the same as line k, not the negative reciprocal, so it would be parallel to k, not perpendicular; also its intercept 4 does not make it pass through $(2,7)$.
**Choice D is incorrect.** Its slope $2/3$ is parallel to k (not perpendicular), and though its intercept 10 would give $y = \frac{2}{3}(2) + 10 = \frac{4}{3} + 10 \ne 7$, so it does not pass through the given point.
**Faster approach:** Identify k’s slope from two grid points, take the negative reciprocal for the perpendicular slope, then plug the given point to solve for the y-intercept.'),
  ('4406aec6-df1a-5451-92ab-1d44d1f3f72c', 1, null, '**Choice B is correct.** To determine whether a data point’s actual y-value is greater than the predicted y-value from the line of best fit, compare the point’s vertical position to the line at the same x-value. Counting the nine plotted points relative to the line, five of them lie above the line (two at the left, one in the middle cluster, and two on the right), so 5 points have actual y greater than predicted.
**Choice A is incorrect.** Only 2 points above the line would undercount the visible points; there are clearly more than two above the line.
**Choice C is incorrect.** Seven points above the line overcounts; inspection shows several points fall below the line in the middle region.
**Choice D is incorrect.** Eight points above the line is also too many; at least two or three points are visibly below the line.
**Faster approach:** For each plotted point, look straight down (or up) to the line at the same x-coordinate — if the point is above that intersection count it as > predicted. Rapidly scan left to right and tally above vs. below to avoid re-evaluating points.'),
  ('2b641475-97c3-5f64-9349-dde09fbe5ba5', 2, null, '**Choice C is correct.** Let $y = 8 - 3x$. The equation becomes $9y + 2 = 8y + 19$. Subtract $8y$ from both sides to get $y + 2 = 19$, then subtract 2 to get $y = 17$. Therefore $8 - 3x = 17$, so Choice C is correct.
**Choice A is incorrect.** Substituting $8 - 3x = -17$ would give $9(-17) + 2 = -153 + 2 = -151$ on the left and $8(-17) + 19 = -136 + 19 = -117$ on the right, which are not equal.
**Choice B is incorrect.** If $8 - 3x = -3$, the left side would be $9(-3) + 2 = -27 + 2 = -25$ and the right $8(-3) + 19 = -24 + 19 = -5$, not equal.
**Choice D is incorrect.** If $8 - 3x = 3$, the left side is $9(3) + 2 = 27 + 2 = 29$ and the right side $8(3) + 19 =$ $24 + 19 = 43$, not equal.
**Faster approach:** Recognize the common expression $8 - 3x$ and set $y = 8 - 3x$ to reduce the equation to a one-step linear equation $9y + 2 = 8y + 19$, then solve for $y$ directly.')
